import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { TreatmentPlanApi } from '../treatmentPlanApi';

// Mock fetch
global.fetch = vi.fn();

describe('TreatmentPlanApi', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  afterEach(() => {
    vi.restoreAllMocks();
  });

  describe('generateStream', () => {
    it('应该成功调用流式 API 并处理 chunks', async () => {
      const mockReader = {
        read: vi.fn()
          .mockResolvedValueOnce({ value: new TextEncoder().encode('治疗'), done: false })
          .mockResolvedValueOnce({ value: new TextEncoder().encode('计划'), done: false })
          .mockResolvedValueOnce({ value: undefined, done: true }),
      };

      const mockResponse = {
        ok: true,
        body: {
          getReader: () => mockReader,
        },
      };

      vi.mocked(fetch).mockResolvedValue(mockResponse as any);

      const chunks: string[] = [];
      const onChunk = (chunk: string) => chunks.push(chunk);

      await TreatmentPlanApi.generateStream('assessment_001', 'patient_001', onChunk);

      expect(chunks).toEqual(['治疗', '计划']);
      expect(fetch).toHaveBeenCalledWith(
        'http://localhost:8000/api/treatment-plan/generate/stream',
        expect.objectContaining({
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: expect.any(String),
        })
      );
    });

    it('应该在 HTTP 错误时抛出异常', async () => {
      const mockResponse = {
        ok: false,
        status: 500,
      };

      vi.mocked(fetch).mockResolvedValue(mockResponse as any);

      await expect(
        TreatmentPlanApi.generateStream('assessment_001', 'patient_001', () => {})
      ).rejects.toThrow('HTTP error! status: 500');
    });

    it('应该在无响应体时抛出异常', async () => {
      const mockResponse = {
        ok: true,
        body: null,
      };

      vi.mocked(fetch).mockResolvedValue(mockResponse as any);

      await expect(
        TreatmentPlanApi.generateStream('assessment_001', 'patient_001', () => {})
      ).rejects.toThrow('No response body');
    });

    it('应该发送正确的请求体', async () => {
      const mockReader = {
        read: vi.fn().mockResolvedValue({ value: undefined, done: true }),
      };

      const mockResponse = {
        ok: true,
        body: { getReader: () => mockReader },
      };

      vi.mocked(fetch).mockResolvedValue(mockResponse as any);

      await TreatmentPlanApi.generateStream('assessment_001', 'patient_001', () => {});

      const callArgs = vi.mocked(fetch).mock.calls[0];
      const requestBody = JSON.parse(callArgs[1]?.body as string);

      expect(requestBody).toEqual({
        patientId: 'patient_001',
        assessmentId: 'assessment_001',
        createdBy: 'system',
      });
    });

    it('应该处理网络错误', async () => {
      vi.mocked(fetch).mockRejectedValue(new Error('Network error'));

      await expect(
        TreatmentPlanApi.generateStream('assessment_001', 'patient_001', () => {})
      ).rejects.toThrow('Network error');
    });

    it('应该处理空的 chunks', async () => {
      const mockReader = {
        read: vi.fn()
          .mockResolvedValueOnce({ value: new TextEncoder().encode(''), done: false })
          .mockResolvedValueOnce({ value: undefined, done: true }),
      };

      const mockResponse = {
        ok: true,
        body: { getReader: () => mockReader },
      };

      vi.mocked(fetch).mockResolvedValue(mockResponse as any);

      const chunks: string[] = [];
      await TreatmentPlanApi.generateStream('assessment_001', 'patient_001', (chunk) => {
        chunks.push(chunk);
      });

      // 空字符串也会被解码并传递
      expect(chunks).toContain('');
    });
  });

  describe('generate', () => {
    it('应该成功调用非流式 API', async () => {
      const mockResponse = {
        ok: true,
        json: vi.fn().mockResolvedValue({
          id: 1,
          content: '治疗计划内容',
          patientId: 'patient_001',
        }),
      };

      vi.mocked(fetch).mockResolvedValue(mockResponse as any);

      const result = await TreatmentPlanApi.generate('assessment_001', 'patient_001');

      expect(result).toEqual({
        id: 1,
        content: '治疗计划内容',
        patientId: 'patient_001',
      });
    });

    it('应该在 HTTP 错误时抛出异常', async () => {
      const mockResponse = {
        ok: false,
        status: 404,
      };

      vi.mocked(fetch).mockResolvedValue(mockResponse as any);

      await expect(
        TreatmentPlanApi.generate('assessment_001', 'patient_001')
      ).rejects.toThrow('HTTP error! status: 404');
    });

    it('应该发送正确的请求体', async () => {
      const mockResponse = {
        ok: true,
        json: vi.fn().mockResolvedValue({}),
      };

      vi.mocked(fetch).mockResolvedValue(mockResponse as any);

      await TreatmentPlanApi.generate('assessment_001', 'patient_001');

      const callArgs = vi.mocked(fetch).mock.calls[0];
      const requestBody = JSON.parse(callArgs[1]?.body as string);

      expect(requestBody).toEqual({
        patientId: 'patient_001',
        assessmentId: 'assessment_001',
        createdBy: 'system',
      });
    });

    it('应该处理网络错误', async () => {
      vi.mocked(fetch).mockRejectedValue(new Error('Connection failed'));

      await expect(
        TreatmentPlanApi.generate('assessment_001', 'patient_001')
      ).rejects.toThrow('Connection failed');
    });

    it('应该处理 JSON 解析错误', async () => {
      const mockResponse = {
        ok: true,
        json: vi.fn().mockRejectedValue(new Error('Invalid JSON')),
      };

      vi.mocked(fetch).mockResolvedValue(mockResponse as any);

      await expect(
        TreatmentPlanApi.generate('assessment_001', 'patient_001')
      ).rejects.toThrow('Invalid JSON');
    });
  });

  describe('API 基础 URL', () => {
    it('应该使用正确的 API 基础 URL', async () => {
      const mockReader = {
        read: vi.fn().mockResolvedValue({ value: undefined, done: true }),
      };

      const mockResponse = {
        ok: true,
        body: { getReader: () => mockReader },
      };

      vi.mocked(fetch).mockResolvedValue(mockResponse as any);

      await TreatmentPlanApi.generateStream('assessment_001', 'patient_001', () => {});

      const url = vi.mocked(fetch).mock.calls[0][0];
      expect(url).toContain('localhost:8000');
    });
  });
});

import { CONFIG } from '@/config';

const API_BASE_URL = CONFIG.api.baseUrl;

export interface SessionTreatmentPlanRequest {
  patientId: string;
  sessionId: string;
  sessionReportId: string;
  sessionReportMarkdown: string;
  insights?: string[];
  recommendations?: string[];
}

export const TreatmentPlanApi = {
  /**
   * 生成治疗计划（流式）
   */
  generateStream: async (
    assessmentId: string,
    patientId: string,
    onChunk: (chunk: string) => void
  ): Promise<void> => {
    try {
      const response = await fetch(`${API_BASE_URL}/api/treatment-plan/generate/stream`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          patientId,
          assessmentId,
          createdBy: 'system', // 实际应该是当前登录的治疗师ID
        }),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const reader = response.body?.getReader();
      if (!reader) {
        throw new Error('No response body');
      }

      const decoder = new TextDecoder();
      let done = false;

      while (!done) {
        const { value, done: doneReading } = await reader.read();
        done = doneReading;
        if (value) {
          const chunk = decoder.decode(value, { stream: true });
          onChunk(chunk);
        }
      }
    } catch (error) {
      console.error('Error generating treatment plan:', error);
      throw error;
    }
  },

  /**
   * 生成治疗计划（非流式）
   */
  generate: async (
    assessmentId: string,
    patientId: string
  ): Promise<any> => {
    try {
      const response = await fetch(`${API_BASE_URL}/api/treatment-plan/generate`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          patientId,
          assessmentId,
          createdBy: 'system', // 实际应该是当前登录的治疗师ID
        }),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      return await response.json();
    } catch (error) {
      console.error('Error generating treatment plan:', error);
      throw error;
    }
  },

  generateStreamFromSessionReport: async (
    payload: SessionTreatmentPlanRequest,
    onChunk: (chunk: string) => void
  ): Promise<void> => {
    try {
      const response = await fetch(`${API_BASE_URL}/api/treatment-plan/generate-from-session-report/stream`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          ...payload,
          createdBy: 'system',
        }),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const reader = response.body?.getReader();
      if (!reader) {
        throw new Error('No response body');
      }

      const decoder = new TextDecoder();
      let done = false;

      while (!done) {
        const { value, done: doneReading } = await reader.read();
        done = doneReading;
        if (value) {
          const chunk = decoder.decode(value, { stream: true });
          onChunk(chunk);
        }
      }
    } catch (error) {
      console.error('Error generating treatment plan from session report:', error);
      throw error;
    }
  },

  generateFromSessionReport: async (
    payload: SessionTreatmentPlanRequest
  ): Promise<any> => {
    try {
      const response = await fetch(`${API_BASE_URL}/api/treatment-plan/generate-from-session-report`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          ...payload,
          createdBy: 'system',
        }),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      return await response.json();
    } catch (error) {
      console.error('Error generating treatment plan from session report:', error);
      throw error;
    }
  },
};

import React, { useEffect, useState, useMemo } from 'react';
import {
  Cloud,
  Search,
  UserPlus,
  Link,
  Trash2,
  X,
  Activity,
  ChevronRight,
  AlertTriangle,
  CheckCircle,
  HelpCircle,
  FileText,
  User,
  ArrowRight,
  TrendingUp,
  RotateCw,
  Copy,
  Key
} from 'lucide-react';
import { 
  IntegrationService, 
  SyncedScreeningBrief, 
  SyncedScreeningDetail 
} from '@/services/integrationService';
import { usePatientStore } from '@/store/usePatientStore';
import { Button } from '@/components/ui';
import { verifySUC } from '@/utils/suc-utils';


interface SquatLabSyncPanelProps {
  isOpen: boolean;
  onClose: () => void;
  onImportSuccess?: (patientName: string) => void;
}

const getInitialFamilyCode = (payload: any): string | null => {
  const code = String(payload?.subject?.subject_id || '').trim().toUpperCase();
  return /^[A-Z0-9]{4,6}$/.test(code) ? code : null;
};

export const SquatLabSyncPanel: React.FC<SquatLabSyncPanelProps> = ({
  isOpen,
  onClose,
  onImportSuccess
}) => {
  const [syncedList, setSyncedList] = useState<SyncedScreeningBrief[]>([]);
  const [selectedSessionId, setSelectedSessionId] = useState<string | null>(null);
  const [detail, setDetail] = useState<SyncedScreeningDetail | null>(null);
  const [loading, setLoading] = useState(false);
  const [detailLoading, setDetailLoading] = useState(false);
  const [actionLoading, setActionLoading] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [error, setError] = useState<string | null>(null);

  // 家庭码展示
  const [generatedCode, setGeneratedCode] = useState<string | null>(null);
  const [codeCopied, setCodeCopied] = useState(false);

  // Link to existing patient states
  const [isLinking, setIsLinking] = useState(false);
  const [patientSearchQuery, setPatientSearchQuery] = useState('');

  const { patients, importSquatLabScreening, loadPatients } = usePatientStore();

  // Load pending list on open
  useEffect(() => {
    if (isOpen) {
      fetchSyncedList();
      setSelectedSessionId(null);
      setDetail(null);
      setIsLinking(false);
    }
  }, [isOpen]);

  // Load detailed session payload
  useEffect(() => {
    if (selectedSessionId) {
      fetchDetail(selectedSessionId);
    } else {
      setDetail(null);
    }
  }, [selectedSessionId]);

  const fetchSyncedList = async () => {
    setLoading(true);
    setError(null);
    try {
      // Fetch only 'pending' (non-imported) records to clear therapist's workspace
      const data = await IntegrationService.getSyncedScreenings('pending');
      setSyncedList(data);
    } catch (err) {
      setError('无法获取同步数据，请检查康复网关服务是否正常启动');
    } finally {
      setLoading(false);
    }
  };

  const fetchDetail = async (id: string) => {
    setDetailLoading(true);
    try {
      const data = await IntegrationService.getSyncedScreeningDetail(id);
      setDetail(data);
    } catch (err) {
      setError('加载早筛档案详情失败');
    } finally {
      setDetailLoading(false);
    }
  };

  // Perform quick import as brand new patient
  const handleImportNew = async (payload: any) => {
    setActionLoading(true);
    setError(null);
    setGeneratedCode(null);
    try {
      const patient = await importSquatLabScreening(payload);
      const result = await IntegrationService.confirmScreeningIntake(payload.session_id, {
        action: 'create_patient',
        patient_id: patient.id,
        patient_code: patient.shortCode,
        short_code: patient.shortCode,
        family_code: getInitialFamilyCode(payload),
      });

      // 展示生成的/返回的家庭码
      if (result.family_code) {
        setGeneratedCode(result.family_code);
      }

      if (onImportSuccess) {
        onImportSuccess(patient.name || '新患者');
      }

      setSelectedSessionId(null);
      fetchSyncedList();
    } catch (err) {
      setError(err instanceof Error ? err.message : '一键建档失败');
    } finally {
      setActionLoading(false);
    }
  };

  // Perform import linking to existing patient
  const handleImportLink = async (payload: any, patientId: string) => {
    setActionLoading(true);
    setError(null);
    setGeneratedCode(null);
    try {
      const patient = await importSquatLabScreening(payload, patientId);
      const result = await IntegrationService.confirmScreeningIntake(payload.session_id, {
        action: 'link_existing_patient',
        patient_id: patient.id,
        patient_code: patient.shortCode,
        short_code: patient.shortCode,
        family_code: getInitialFamilyCode(payload),
      });

      // 如果生成了新家庭码，展示出来
      if (result.family_code) {
        setGeneratedCode(result.family_code);
      }

      if (onImportSuccess) {
        onImportSuccess(patient.name || '已绑定患者');
      }

      setIsLinking(false);
      setSelectedSessionId(null);
      fetchSyncedList();
    } catch (err) {
      setError(err instanceof Error ? err.message : '关联导入失败');
    } finally {
      setActionLoading(false);
    }
  };

  const handleDeleteRecord = async (sessionId: string) => {
    if (!window.confirm('确认要物理删除此条同步记录吗？该操作不会影响早筛终端的数据。')) return;
    setActionLoading(true);
    try {
      await IntegrationService.deleteSyncedScreening(sessionId);
      setSelectedSessionId(null);
      fetchSyncedList();
    } catch (err) {
      setError('删除失败');
    } finally {
      setActionLoading(false);
    }
  };

  // Filter list by keyword
  const filteredList = useMemo(() => {
    const q = searchQuery.toLowerCase().trim();
    if (!q) return syncedList;
    return syncedList.filter(s => 
      s.subject_display_name.toLowerCase().includes(q) || 
      s.session_id.toLowerCase().includes(q) ||
      (s.subject_id && s.subject_id.toLowerCase().includes(q))
    );
  }, [syncedList, searchQuery]);

  // Filter clinical patients list to select link candidate
  const filteredPatients = useMemo(() => {
    const q = patientSearchQuery.toLowerCase().trim();
    if (!q) return patients.slice(0, 10); // Display top 10 as default
    return patients.filter(p => 
      (p.name && p.name.toLowerCase().includes(q)) || 
      (p.shortCode && p.shortCode.toLowerCase().includes(q)) ||
      p.id.toLowerCase().includes(q)
    );
  }, [patients, patientSearchQuery]);

  if (!isOpen) return null;

  const isSUCLike = searchQuery.trim().startsWith('QY-') || searchQuery.split('-').length === 5;
  const isInvalidSUC = isSUCLike && !verifySUC(searchQuery.trim());

  return (
    <div className="fixed inset-0 z-[999] flex justify-end overflow-hidden bg-slate-900/30 backdrop-blur-sm animate-fade-in">
      {/* CSS overrides inside panel for perfect isolated glassmorphism styling */}
      <style>{`
        .glass-blur-panel {
          background: rgba(255, 255, 255, 0.75);
          backdrop-filter: blur(28px) saturate(190%);
          -webkit-backdrop-filter: blur(28px) saturate(190%);
          border-left: 1px solid rgba(255, 255, 255, 0.4);
          box-shadow: -10px 0 40px rgba(15, 23, 42, 0.15);
        }
        .detail-glow-card {
          background: rgba(255, 255, 255, 0.4);
          border: 1px solid rgba(255, 255, 255, 0.6);
          border-radius: 12px;
          transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
        }
        .detail-glow-card:hover {
          background: rgba(255, 255, 255, 0.65);
          transform: translateY(-2px);
          box-shadow: 0 10px 20px rgba(0, 0, 0, 0.03);
        }
        .animate-fade-in {
          animation: panelFadeIn 0.3s cubic-bezier(0.16, 1, 0.3, 1) forwards;
        }
        @keyframes panelFadeIn {
          from { opacity: 0; }
          to { opacity: 1; }
        }
        .slide-in-right {
          animation: slideInRight 0.4s cubic-bezier(0.16, 1, 0.3, 1) forwards;
        }
        @keyframes slideInRight {
          from { transform: translateX(100%); }
          to { transform: translateX(0); }
        }
      `}</style>

      {/* Click backdrop to close */}
      <div className="flex-1" onClick={onClose}></div>

      {/* Synchronize Master Drawer Panel */}
      <div className="glass-blur-panel slide-in-right relative flex h-full w-[450px] flex-col text-slate-800 md:w-[600px] xl:w-[720px]">
        {/* Header bar */}
        <div className="flex items-center justify-between border-b border-slate-200/60 p-4">
          <div className="flex items-center gap-2">
            <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-blue-500/10 text-blue-600">
              <Cloud className="animate-pulse" size={22} />
            </div>
            <div>
              <h2 className="text-lg font-bold text-slate-900">早筛同步中心</h2>
              <p className="text-xs text-slate-500">从学校体态与脊柱侧弯三联筛查终端实时接入数据</p>
            </div>
          </div>
          <button onClick={onClose} className="rounded-lg p-2 text-slate-400 hover:bg-slate-100 hover:text-slate-700">
            <X size={20} />
          </button>
        </div>

        {/* Global Error Alert */}
        {error && (
          <div className="m-4 flex items-start gap-2.5 rounded-xl border border-red-200 bg-red-50/80 p-3.5 text-sm text-red-800">
            <AlertTriangle className="mt-0.5 shrink-0" size={16} />
            <div className="flex-1">
              <p className="font-medium">同步服务异常</p>
              <p className="mt-0.5 text-xs text-red-700/90">{error}</p>
            </div>
            <button onClick={() => setError(null)} className="text-xs font-semibold text-red-500 hover:text-red-700">忽略</button>
          </div>
        )}

        {/* 家庭码生成成功提示 */}
        {generatedCode && (
          <div className="m-4 flex items-center gap-3 rounded-xl border border-emerald-200 bg-emerald-50/90 p-3.5 shadow-sm">
            <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-emerald-100 text-emerald-700">
              <Key size={18} />
            </div>
            <div className="flex-1 min-w-0">
              <p className="text-xs font-semibold text-emerald-800">家庭码已生成，请告知家长</p>
              <p className="mt-0.5 font-mono text-lg font-bold tracking-[0.2em] text-emerald-900">{generatedCode}</p>
            </div>
            <Button
              variant="secondary"
              size="sm"
              icon={codeCopied ? <CheckCircle size={14} /> : <Copy size={14} />}
              onClick={async () => {
                if (!generatedCode) return;
                await navigator.clipboard.writeText(generatedCode);
                setCodeCopied(true);
                setTimeout(() => setCodeCopied(false), 1200);
              }}
            >
              {codeCopied ? '已复制' : '复制'}
            </Button>
            <button
              onClick={() => setGeneratedCode(null)}
              className="text-slate-400 hover:text-slate-600"
            >
              <X size={16} />
            </button>
          </div>
        )}

        {/* Session master split view */}
        <div className="flex flex-1 overflow-hidden">
          {/* LEFT LIST PANEL */}
          <div className="flex flex-1 flex-col overflow-y-auto border-r border-slate-200/50 p-4 custom-scrollbar">
            {/* Search Input bar */}
            <div className="relative mb-3">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={15} />
              <input
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="搜索姓名、早筛ID或SUC编码..."
                className={`w-full rounded-xl border bg-white/70 py-2 pl-9 pr-4 text-sm focus:outline-none transition-all ${
                  isInvalidSUC 
                    ? 'border-red-400 focus:border-red-500 text-red-900 bg-red-50/30' 
                    : 'border-slate-200/80 focus:border-blue-500'
                }`}
              />
              {isInvalidSUC && (
                <p className="mt-1 text-[11px] text-red-600 flex items-center gap-1 pl-1 animate-pulse">
                  <AlertTriangle size={12} className="shrink-0" />
                  <span>统一编码校验位(Luhn-10)有误，请核对</span>
                </p>
              )}
            </div>

            {/* List entries */}
            {loading ? (
              <div className="flex flex-1 flex-col items-center justify-center p-8 text-slate-400">
                <RotateCw className="animate-spin text-blue-500" size={24} />
                <p className="mt-2 text-xs">正在轮询最新的早筛记录...</p>
              </div>
            ) : filteredList.length === 0 ? (
              <div className="flex flex-1 flex-col items-center justify-center p-8 text-center text-slate-400">
                <Cloud size={40} className="stroke-[1.2] text-slate-300" />
                <p className="mt-3 text-sm font-medium text-slate-600">暂无待入档的筛查记录</p>
                <p className="mt-1 text-xs text-slate-400 max-w-[240px]">
                  请在早筛端 (Port 5174) 报告底部点击“同步至康复工作台”按钮推送记录
                </p>
                <Button variant="secondary" className="mt-4" onClick={fetchSyncedList}>
                  刷新列表
                </Button>
              </div>
            ) : (
              <div className="space-y-2">
                <div className="flex items-center justify-between text-xs text-slate-400 px-1">
                  <span>待处理数据 ({filteredList.length} 条)</span>
