import React, { useEffect, useState } from 'react';
import { ReportFormat, ReportGenerator, ReportType } from '../../services/ReportGenerator';
import { formatDate } from '../assessment/utils/assessmentHistoryUtils';
import { Button } from '../ui/Button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '../ui/Card';
import { ReportViewer } from './ReportViewer';

interface ReportCenterProps {
  patientId: string;
}

export const ReportCenter: React.FC<ReportCenterProps> = ({ patientId }) => {
  const [reports, setReports] = useState<any[]>([]);
  const [selectedReport, setSelectedReport] = useState<any>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [showGenerator, setShowGenerator] = useState(false);

  const [reportConfig, setReportConfig] = useState({
    type: 'comprehensive' as ReportType,
    format: 'markdown' as ReportFormat,
    patientId,
    timeRange: {
      start: new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).getTime(),
      end: Date.now(),
    },
    includeCharts: true,
    includeRecommendations: true,
    includeRawData: false,
  });

  useEffect(() => {
    loadReports();
  }, [patientId]);

  const loadReports = () => {
    setReports(ReportGenerator.loadReports(patientId));
  };

  const handleGenerateReport = async () => {
    setIsGenerating(true);
    try {
      const report = await ReportGenerator.generateReport(reportConfig);
      ReportGenerator.saveReport(report);
      loadReports();
      setSelectedReport(report);
      setShowGenerator(false);
    } catch (error) {
      console.error('生成报告失败:', error);
    } finally {
      setIsGenerating(false);
    }
  };

  const handleDeleteReport = (reportId: string) => {
    if (!window.confirm('确定要删除这份报告吗？')) return;

    ReportGenerator.deleteReport(reportId);
    loadReports();
    if (selectedReport?.id === reportId) {
      setSelectedReport(null);
    }
  };

  const handleExportReport = (report: any) => {
    const blob = new Blob([report.content], {
      type: report.format === 'markdown' ? 'text/markdown' : 'text/html',
    });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = `${report.title.replace(/\s+/g, '_')}.${report.format}`;
    document.body.appendChild(anchor);
    anchor.click();
    document.body.removeChild(anchor);
    URL.revokeObjectURL(url);
  };

  const reportListItemClass = (active: boolean) =>
    active
      ? 'rounded-xl border border-blue-500 bg-blue-50 p-3 cursor-pointer transition-all'
      : 'rounded-xl border border-slate-200 bg-white p-3 cursor-pointer transition-all hover:border-slate-300';

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h2 className="text-2xl font-bold text-slate-900">报告中心</h2>
        <Button onClick={() => setShowGenerator(true)}>生成新报告</Button>
      </div>

      {showGenerator ? (
        <Card>
          <CardHeader>
            <CardTitle>生成报告</CardTitle>
            <CardDescription>配置报告生成选项</CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
              <div className="space-y-2">
                <label className="text-sm font-medium text-slate-700">报告类型</label>
                <select
                  value={reportConfig.type}
                  onChange={(event) =>
                    setReportConfig({ ...reportConfig, type: event.target.value as ReportType })
                  }
                  className="field-select"
                >
                  <option value="assessment">评估报告</option>
                  <option value="treatment">治疗计划报告</option>
                  <option value="progress">康复进度报告</option>
                  <option value="comprehensive">综合康复报告</option>
                </select>
              </div>

              <div className="space-y-2">
                <label className="text-sm font-medium text-slate-700">报告格式</label>
                <select
                  value={reportConfig.format}
                  onChange={(event) =>
                    setReportConfig({
                      ...reportConfig,
                      format: event.target.value as ReportFormat,
                    })
                  }
                  className="field-select"
                >
                  <option value="markdown">Markdown</option>
                  <option value="html">HTML</option>
                  <option value="pdf">PDF</option>
                </select>
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium text-slate-700">时间范围</label>
              <div className="flex gap-2">
                <input
                  type="date"
                  value={new Date(reportConfig.timeRange.start).toISOString().split('T')[0]}
                  onChange={(event) =>
                    setReportConfig({
                      ...reportConfig,
                      timeRange: {
                        ...reportConfig.timeRange,
                        start: new Date(event.target.value).getTime(),
                      },
                    })
                  }
                  className="field-input flex-1"
                />
                <input
                  type="date"
                  value={new Date(reportConfig.timeRange.end).toISOString().split('T')[0]}
                  onChange={(event) =>
                    setReportConfig({
                      ...reportConfig,
                      timeRange: {
                        ...reportConfig.timeRange,
                        end: new Date(event.target.value).getTime(),
                      },
                    })
                  }
                  className="field-input flex-1"
                />
              </div>
            </div>

            <div className="flex gap-2">
              <Button onClick={handleGenerateReport} disabled={isGenerating}>
                {isGenerating ? '生成中...' : '生成报告'}
              </Button>
              <Button variant="outline" onClick={() => setShowGenerator(false)}>
                取消
              </Button>
            </div>
          </CardContent>
        </Card>
      ) : null}

      <div className="grid grid-cols-1 gap-4 lg:grid-cols-3">
        <div className="lg:col-span-1">
          <Card>
            <CardHeader>
              <CardTitle>报告列表</CardTitle>
              <CardDescription>所有已生成报告</CardDescription>
            </CardHeader>
            <CardContent>
              <div className="space-y-2">
                {reports.length === 0 ? (
                  <div className="state-panel">
                    <p>暂无报告</p>
                  </div>
                ) : (
                  reports.map((report) => (
                    <div
                      key={report.id}
                      className={reportListItemClass(selectedReport?.id === report.id)}
                      onClick={() => setSelectedReport(report)}
                    >
                      <div className="flex items-start justify-between">
                        <h3 className="font-medium text-slate-900">{report.title}</h3>
                        <div className="flex gap-1">
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={(event) => {
                              event.stopPropagation();
                              handleExportReport(report);
                            }}
                          >
                            导出
                          </Button>
                          <Button
                            variant="danger"
                            size="sm"
                            onClick={(event) => {
                              event.stopPropagation();
                              handleDeleteReport(report.id);
                            }}
                          >
                            删除
                          </Button>
                        </div>
                      </div>
                      <p className="text-sm text-slate-600">
                        生成时间: {formatDate(new Date(report.createdAt).toISOString())}
                      </p>
                      <p className="text-xs text-slate-500">
                        类型: {report.type} | 格式: {report.format}
                      </p>
                    </div>
                  ))
                )}
              </div>
            </CardContent>
          </Card>
        </div>

        <div className="lg:col-span-2">
          {selectedReport ? (
            <ReportViewer report={selectedReport} />
          ) : (
            <Card>
              <CardContent className="flex h-64 items-center justify-center">
                <p className="text-slate-500">请选择或生成一份报告</p>
              </CardContent>
            </Card>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { formatDate } from '../assessment/utils/assessmentHistoryUtils';
import { Button } from '../ui/Button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '../ui/Card';

interface ReportViewerProps {
  report: {
    id: string;
    patientId: string;
    type: string;
    format: string;
    title: string;
    content: string;
    createdAt: number;
    data: any;
  };
}

export const ReportViewer: React.FC<ReportViewerProps> = ({ report }) => {
  const [activeTab, setActiveTab] = useState('content');

  const handlePrint = () => {
    window.print();
  };

  const renderMarkdownContent = (content: string) => {
    // 简单的 Markdown 渲染
    const html = content
      .replace(/^# (.*$)/gim, '<h1>$1</h1>')
      .replace(/^## (.*$)/gim, '<h2>$1</h2>')
      .replace(/^### (.*$)/gim, '<h3>$1</h3>')
      .replace(/\*\*(.*?)\*\*/gim, '<strong>$1</strong>')
      .replace(/\*(.*?)\*/gim, '<em>$1</em>')
      .replace(/\[(.*?)\]\((.*?)\)/gim, '<a href="$2">$1</a>')
      .replace(/^\- (.*$)/gim, '<li>$1</li>')
      .replace(/(<li>.*<\/li>)/s, '<ul>$1</ul>')
      .replace(/\n/gim, '<br>');

    return <div dangerouslySetInnerHTML={{ __html: html }} />;
  };

  const renderHtmlContent = (content: string) => {
    return <div dangerouslySetInnerHTML={{ __html: content }} />;
  };

  const renderPdfContent = (content: string) => {
    return (
      <div className="py-8 text-center">
        <p>PDF 格式报告需要下载后查看</p>
        <Button
          onClick={() => {
            const blob = new Blob([content], { type: 'application/pdf' });
            const url = URL.createObjectURL(blob);
            window.open(url, '_blank');
          }}
        >
          打开 PDF
        </Button>
      </div>
    );
  };

  const renderContent = () => {
    switch (report.format) {
      case 'markdown':
        return renderMarkdownContent(report.content);
      case 'html':
        return renderHtmlContent(report.content);
      case 'pdf':
        return renderPdfContent(report.content);
      default:
        return <p>不支持的报告格式</p>;
    }
  };

  return (
    <Card className="h-full">
      <CardHeader>
        <div className="flex items-start justify-between">
          <div>
            <CardTitle>{report.title}</CardTitle>
            <CardDescription>
              生成时间: {formatDate(new Date(report.createdAt).toISOString())}
            </CardDescription>
            <CardDescription className="mt-1">
              类型: {report.type} | 格式: {report.format}
            </CardDescription>
          </div>
          <Button onClick={handlePrint} variant="outline" size="sm">
            打印报告
          </Button>
        </div>
      </CardHeader>
      <CardContent className="h-[600px] overflow-auto">
        <div className="mb-4 border-b border-slate-200 pb-4">
          <div className="segmented-control w-fit">
            <button
              className={`segmented-control-tab ${activeTab === 'content' ? 'segmented-control-tab-solid' : 'segmented-control-tab-inactive'}`}
              onClick={() => setActiveTab('content')}
            >
              报告内容
            </button>
            <button
              className={`segmented-control-tab ${activeTab === 'data' ? 'segmented-control-tab-solid' : 'segmented-control-tab-inactive'}`}
              onClick={() => setActiveTab('data')}
            >
              原始数据
            </button>
          </div>
        </div>

        {activeTab === 'content' ? (
          <div className="space-y-4">
            <div className="prose max-w-none">{renderContent()}</div>
          </div>
        ) : null}

        {activeTab === 'data' ? (
          <div className="space-y-4">
            <div className="rounded-lg bg-gray-50 p-4">
              <h3 className="mb-2 font-medium">评估数据</h3>
              <pre className="overflow-x-auto text-sm">
                {JSON.stringify(report.data.assessments, null, 2)}
              </pre>
            </div>
            <div className="rounded-lg bg-gray-50 p-4">
              <h3 className="mb-2 font-medium">治疗计划</h3>
              <pre className="overflow-x-auto text-sm">
                {JSON.stringify(report.data.treatmentPlans, null, 2)}
              </pre>
            </div>
            <div className="rounded-lg bg-gray-50 p-4">
              <h3 className="mb-2 font-medium">评估记录</h3>
              <pre className="overflow-x-auto text-sm">
                {JSON.stringify(report.data.records, null, 2)}
              </pre>
            </div>
            <div className="rounded-lg bg-gray-50 p-4">
              <h3 className="mb-2 font-medium">指标数据</h3>
              <pre className="overflow-x-auto text-sm">
                {JSON.stringify(report.data.metrics, null, 2)}
              </pre>
            </div>
            <div className="rounded-lg bg-gray-50 p-4">
              <h3 className="mb-2 font-medium">洞察</h3>
              <pre className="overflow-x-auto text-sm">
                {JSON.stringify(report.data.insights, null, 2)}
              </pre>
            </div>
          </div>
        ) : null}
      </CardContent>
    </Card>
  );
};

import React, { useEffect, useState } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { FileText, Loader2, AlertCircle } from 'lucide-react';
import { COLORS } from '@/constants/uiStyles';

interface MarkdownReportProps {
  content: string | null;
  loading?: boolean;
  className?: string;
  animate?: boolean;
  showChrome?: boolean;
  title?: string;
  subtitle?: string;
  footerNote?: string;
  tone?: 'blue' | 'cyan' | 'violet';
  emptyTitle?: string;
  emptyDescription?: string;
}

const toneClassMap = {
  blue: {
    iconBg: 'bg-blue-500/10',
    iconText: 'text-blue-600',
    strong: 'text-blue-700',
    quote: 'border-blue-500 bg-blue-50 text-slate-700',
    dot: 'bg-emerald-500',
  },
  cyan: {
    iconBg: 'bg-cyan-500/10',
    iconText: 'text-cyan-600',
    strong: 'text-cyan-700',
    quote: 'border-cyan-500 bg-cyan-50 text-slate-700',
    dot: 'bg-cyan-500',
  },
  violet: {
    iconBg: 'bg-violet-500/10',
    iconText: 'text-violet-600',
    strong: 'text-violet-700',
    quote: 'border-violet-500 bg-violet-50 text-slate-700',
    dot: 'bg-violet-500',
  },
} as const;

const mojibakeTokens = [
  '\u951F',
  '\u93C2',
  '\u9369',
  '\u93B6',
  '\u7487',
  '\u7039',
  '\u7F01',
  '\u9357',
  '\u95B2',
  '\u9350',
  '\u935A',
  '\u93B5',
  '\u59F9\u56E8\u20AC',
  '\u5BEE\u509A\u7236',
  '\uFFFD',
];
const mojibakePattern = new RegExp(mojibakeTokens.join('|'), 'u');
const suspiciousPhoneticPattern = /[\u3100-\u312F]/u;
const viewLabelMap = {
  front: '正面',
  side: '侧面',
  back: '背面',
} as const;

const normalizeMarkdownLine = (line: string) => {
  const withoutControlChars = line.replace(/[\uFEFF\u200B-\u200D\u2060]/g, '').trimEnd();
  const withHeadingSpace = withoutControlChars.replace(/^(#{1,6})([^\s#].*)$/, '$1 $2');

  return withHeadingSpace
    .replace(/^(#{1,6})\s*(front|side|back)\b.*$/i, (_, hashes: string, view: keyof typeof viewLabelMap) => `${hashes} ${viewLabelMap[view]}评估`)
    .replace(/^评估视角[:：]\s*(front|side|back)\b.*$/i, (_, view: keyof typeof viewLabelMap) => `评估视角：${viewLabelMap[view]}`);
};

const shouldDropMarkdownLine = (line: string) => {
  const trimmed = line.trim();
  if (!trimmed) {
    return false;
  }

  return mojibakePattern.test(trimmed) || suspiciousPhoneticPattern.test(trimmed);
};

export const sanitizeMarkdownContent = (content?: string | null) => {
  if (typeof content !== 'string') {
    return '';
  }

  const normalized = content.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
  const cleanedLines = normalized
    .split('\n')
    .map(normalizeMarkdownLine)
    .filter((line) => !shouldDropMarkdownLine(line));

  return cleanedLines
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
};

export const sanitizeReadableText = (content?: string | null) =>
  sanitizeMarkdownContent(content).replace(/\n{2,}/g, '\n\n').trim();

export const MarkdownReport: React.FC<MarkdownReportProps> = ({
  content,
  loading = false,
  className = '',
  animate = true,
  showChrome = true,
  title = 'AI 康复评估报告',
  subtitle = '基于当前采集数据生成',
  footerNote = '报告由 Rehab-AI 生成，仅供临床参考。',
  tone = 'blue',
  emptyTitle = '暂无报告内容',
  emptyDescription = '完成评估后，报告会显示在这里。',
}) => {
  const [displayedContent, setDisplayedContent] = useState('');
  const rawContent = typeof content === 'string' ? content.trim() : '';
  const normalizedContent = sanitizeMarkdownContent(content);
  const contentFiltered = Boolean(rawContent) && !normalizedContent;
  const toneClasses = toneClassMap[tone];

  useEffect(() => {
    if (!normalizedContent) {
      setDisplayedContent('');
      return;
    }

    if (!animate) {
      setDisplayedContent(normalizedContent);
      return;
    }

    let currentIdx = 0;
    const interval = setInterval(() => {
      if (currentIdx < normalizedContent.length) {
        setDisplayedContent(normalizedContent.substring(0, currentIdx + 1));
        currentIdx += 10;
      } else {
        clearInterval(interval);
      }
    }, 10);

    return () => clearInterval(interval);
  }, [normalizedContent, animate]);

  if (loading) {
    return (
      <div className={`flex flex-col items-center justify-center p-10 min-h-[240px] rounded-2xl border border-slate-200 bg-slate-50 ${className}`}>
        <Loader2 className={`mb-4 h-9 w-9 animate-spin ${toneClasses.iconText}`} />
        <p className="text-sm font-semibold text-slate-900">{'\u6b63\u5728\u751f\u6210\u62a5\u544a'}</p>
        <p className="mt-2 text-center text-sm text-slate-500">{'\u7cfb\u7edf\u6b63\u5728\u6574\u7406\u5f53\u524d\u4f53\u6001\u6570\u636e\uff0c\u8bf7\u7a0d\u5019\u3002'}</p>
      </div>
    );
  }

  if (!normalizedContent) {
    return (
      <div className={`flex min-h-[220px] flex-col items-center justify-center rounded-2xl border border-dashed border-slate-200 bg-slate-50/80 p-10 text-center ${className}`}>
        <FileText className="mb-4 h-10 w-10 text-slate-300" />
        <p className="text-sm font-semibold text-slate-900">{emptyTitle}</p>
        <p className="mt-2 max-w-md text-sm text-slate-500">
          {contentFiltered ? '报告内容存在异常字符，已自动过滤；请稍后查看清洗后的内容。' : emptyDescription}
        </p>
      </div>
    );
  }

  const contentBody = (
    <div className={showChrome ? 'flex-1 overflow-y-auto p-5 lg:p-6 custom-scrollbar' : 'p-5 lg:p-6'}>
      <div className={`max-w-none leading-relaxed ${COLORS.neutral.light.text}`}>
        <ReactMarkdown
          remarkPlugins={[remarkGfm]}
          components={{
            h1: ({ ...props }) => <h1 className="mb-4 mt-6 border-b border-slate-200 pb-2 text-2xl font-bold first:mt-0" {...props} />,
            h2: ({ ...props }) => <h2 className="mb-3 mt-6 text-xl font-bold first:mt-0" {...props} />,
            h3: ({ ...props }) => <h3 className={`mb-2 mt-5 text-lg font-bold first:mt-0 ${toneClasses.strong}`} {...props} />,
            p: ({ ...props }) => <p className="mb-4 leading-7 text-slate-700" {...props} />,
            ul: ({ ...props }) => <ul className="mb-4 list-disc space-y-1 pl-5 text-slate-700" {...props} />,
            ol: ({ ...props }) => <ol className="mb-4 list-decimal space-y-1 pl-5 text-slate-700" {...props} />,
            li: ({ ...props }) => <li className="leading-7" {...props} />,
            blockquote: ({ ...props }) => <blockquote className={`my-4 rounded-r-xl border-l-4 px-4 py-3 italic ${toneClasses.quote}`} {...props} />,
            table: ({ ...props }) => (
              <div className="my-6 overflow-x-auto rounded-xl border border-slate-200">
                <table className="w-full border-collapse text-sm" {...props} />
              </div>
            ),
            th: ({ ...props }) => <th className="border border-slate-200 bg-slate-100 px-4 py-2 text-left font-semibold text-slate-800" {...props} />,
            td: ({ ...props }) => <td className="border border-slate-200 px-4 py-2 text-slate-700" {...props} />,
            strong: ({ ...props }) => <strong className={`font-semibold ${toneClasses.strong}`} {...props} />,
            code: ({ ...props }) => <code className="rounded bg-slate-100 px-1.5 py-0.5 font-mono text-sm text-slate-800" {...props} />,
            hr: ({ ...props }) => <hr className="my-8 border-slate-200" {...props} />,
          }}
        >
          {displayedContent}
        </ReactMarkdown>
      </div>
    </div>
  );

  if (!showChrome) {
    return (
      <div className={`min-h-[220px] rounded-2xl border border-slate-200 bg-white ${className}`}>
        {contentBody}
      </div>
    );
  }

  return (
    <div className={`flex h-full flex-col overflow-hidden rounded-3xl border ${COLORS.neutral.light.border} ${COLORS.neutral.light.bg} ${className}`}>
      <div className={`flex items-center justify-between border-b ${COLORS.neutral.light.borderSoft} ${COLORS.neutral.light.bgSoft} px-6 py-4`}>
        <div className="flex items-center gap-3">
          <div className={`rounded-lg p-2 ${toneClasses.iconBg}`}>
            <FileText className={`h-5 w-5 ${toneClasses.iconText}`} />
          </div>
          <div>
            <h3 className={`font-semibold ${COLORS.neutral.light.text}`}>{title}</h3>
            <p className="text-xs text-slate-500">{subtitle}</p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <span className={`h-2 w-2 rounded-full ${toneClasses.dot}`} />
          <span className={`text-[10px] font-bold uppercase tracking-wider ${COLORS.neutral.light.textMuted}`}>Report Ready</span>
        </div>
      </div>

      {contentBody}

      <div className={`flex items-center gap-2 border-t ${COLORS.neutral.light.borderSoft} ${COLORS.neutral.light.bgSoft} px-6 py-3 text-[11px] italic text-slate-500`}>
        <AlertCircle className="h-3 w-3" />
        {footerNote}
      </div>
    </div>
  );
};

import React from 'react';
import { 
  RotateCcw, 
  Share2, 
  Download,
  CheckCircle,
  BrainCircuit,
  Activity,
  ChevronDown,
  ArrowUpRight
} from 'lucide-react';
import { MarkdownReport } from './MarkdownReport';
import { cn } from '@/lib/utils';
import { COLORS } from '@/constants/uiStyles';

interface PostureReportViewerProps {
  /** 基础报告 - 根据规则得出的结论 */
  auxiliaryDiagnosis?: string | null;
  /** 深度报告 - LLM解析的报告 */
  markdownReport?: string | null;
  /** 当前报告类型 */
  reportType?: 'auxiliary' | 'deep';
  /** 设置报告类型 */
  setReportType?: (type: 'auxiliary' | 'deep') => void;
  /** 是否正在分析中 */
  isAnalyzing?: boolean;
  /** 重置回调 */
  onReset?: () => void;
  /** 标题 */
  title?: string;
  /** 副标题 */
  subtitle?: string;
  /** 是否显示切换按钮 */
  showToggle?: boolean;
  /** 是否全屏 */
  isFullscreen?: boolean;
  /** 设置全屏 */
  setIsFullscreen?: (value: boolean) => void;
  /** 关闭回调 */
  onClose?: () => void;
  /** 额外的类名 */
  className?: string;
  /** 是否内嵌模式（非弹窗） */
  inline?: boolean;
}

/**
 * 体态报告查看器 - 共享组件
 * 
 * 统一显示基础报告（规则结论）和深度报告（LLM解析）
 * 支持弹窗模式和内嵌模式
 */
export const PostureReportViewer: React.FC<PostureReportViewerProps> = ({
  auxiliaryDiagnosis,
  markdownReport,
  reportType = 'deep',
  setReportType,
  isAnalyzing = false,
  onReset,
  title = '体态深度评估报告',
  subtitle = 'NEXUS HUB AI POWERED ANALYSIS',
  showToggle = true,
  isFullscreen = false,
  setIsFullscreen,
  onClose,
  className,
  inline = false
}) => {
  // 确定当前要显示的内容
  const currentContent = reportType === 'deep' ? markdownReport : auxiliaryDiagnosis;
  const hasBothReports = !!auxiliaryDiagnosis && !!markdownReport;
  const isLoading = isAnalyzing && !currentContent;
  const toggleButtonBaseClass = 'px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-wider transition-all';
  const toggleContainerClass = 'segmented-control rounded-xl';
  const toggleButtonClass = (active: boolean, tone: 'blue' | 'violet') =>
    cn(
      toggleButtonBaseClass,
      active ? `bg-white shadow-sm ${tone === 'blue' ? 'text-blue-600' : 'text-purple-600'}` : 'text-slate-400 hover:text-slate-600',
    );
  const headerShellClass = 'p-6 sticky top-0 z-10 border-b border-slate-100 bg-white/80 backdrop-blur-md';
  const headerIconClass = (tone: 'deep' | 'auxiliary') =>
    cn('w-10 h-10 rounded-2xl flex items-center justify-center', tone === 'deep' ? 'bg-purple-50 text-purple-500' : 'bg-blue-50 text-blue-500');
  const headerTitleClass = cn('font-black uppercase tracking-tight', COLORS.neutral.light.text);
  const headerSubtitleClass = cn('text-[10px] font-bold uppercase tracking-widest', COLORS.neutral.light.textLight);
  const chromeButtonClass = cn('p-3 rounded-2xl transition-all', COLORS.neutral.light.textLight, COLORS.neutral.light.hover, COLORS.neutral.light.hoverText);
  const emptyStateShellClass = 'p-8 rounded-[3rem] border border-dashed border-slate-200 bg-slate-50/50';
  const emptyStateTitleClass = cn('mb-3 text-lg font-black uppercase tracking-[0.2em]', COLORS.neutral.light.text);
  const emptyStateBodyClass = cn('max-w-[240px] text-[11px] font-bold leading-relaxed', COLORS.neutral.light.textLight);
  const emptyStateIconShellClass = cn('mb-6 flex h-20 w-20 items-center justify-center rounded-3xl', COLORS.neutral.light.selected);
  const inlineReportShellClass = 'flex-1 overflow-hidden rounded-[2.5rem] border border-slate-200/60 bg-slate-50/80 flex flex-col';
  const resetButtonClass = cn('flex-1 flex items-center justify-center gap-3 rounded-2xl border py-4 text-[10px] font-black uppercase tracking-[0.2em] transition-all', COLORS.neutral.light.border, COLORS.neutral.light.bg, COLORS.neutral.light.text, COLORS.neutral.light.hover);
  const modalShellClass = 'relative flex flex-col overflow-hidden bg-white shadow-2xl transition-all duration-500 ease-in-out';
  const modalBodyClass = 'flex-1 overflow-y-auto bg-slate-900 p-0';

  // 报告类型切换按钮
  const ReportTypeToggle = () => {
    if (!showToggle || !hasBothReports || !setReportType) return null;
    
    return (
      <div className={toggleContainerClass}>
        <button
          onClick={() => setReportType('auxiliary')}
          className={toggleButtonClass(reportType === 'auxiliary', 'blue')}
        >
          基础报告
        </button>
        <button
          onClick={() => setReportType('deep')}
          className={toggleButtonClass(reportType === 'deep', 'violet')}
        >
          深度报告
        </button>
      </div>
    );
  };

  // 头部组件
  const Header = () => (
    <div className={cn(
      "flex items-center justify-between",
      inline ? "mb-6" : headerShellClass
    )}>
      <div className="flex items-center gap-4">
        <div className={headerIconClass(reportType === 'deep' ? 'deep' : 'auxiliary')}>
          {reportType === 'deep' ? <BrainCircuit size={20} /> : <Activity size={20} />}
        </div>
        <div>
          <h3 className={headerTitleClass}>{title}</h3>
          <p className={headerSubtitleClass}>{subtitle}</p>
        </div>
      </div>
      
      <div className="flex items-center gap-4">
        <ReportTypeToggle />
        
        {!inline && onClose && (
          <div className="flex items-center gap-2">
            {setIsFullscreen && (
              <button 
                onClick={() => setIsFullscreen(!isFullscreen)}
                className={cn(chromeButtonClass, 'hidden md:block')}
                title={isFullscreen ? "退出全屏" : "全屏预览"}
              >
                <ArrowUpRight size={20} className={isFullscreen ? "rotate-180" : ""} />
              </button>
            )}
            <button 
              onClick={onClose}
              className={chromeButtonClass}
            >
              <ChevronDown size={20} className="rotate-180" />
            </button>
          </div>
        )}
      </div>
    </div>
  );

  // 加载状态
  if (isLoading) {
    return (
      <div className={cn(
        "flex flex-col items-center justify-center text-center",
        inline ? emptyStateShellClass : "h-full"
      )}>
        <div className="w-20 h-20 rounded-3xl bg-antey-primary/10 flex items-center justify-center mb-6 animate-pulse">
          <BrainCircuit className="text-antey-primary" size={40} />
        </div>
        <h4 className={emptyStateTitleClass}>
          正在生成报告
        </h4>
        <p className={emptyStateBodyClass}>
          AI 正在分析您的体态数据，请稍候...
        </p>
        <div className="mt-8 flex gap-2">
          {[0, 1, 2].map(i => (
            <div 
              key={i} 
              className="w-2 h-2 rounded-full bg-antey-primary/30 animate-bounce" 
              style={{ animationDelay: `${i * 0.2}s` }} 
            />
          ))}
        </div>
      </div>
    );
  }

  // 无内容状态
  if (!currentContent) {
    return (
      <div className={cn(
        "flex flex-col items-center justify-center text-center",
        inline ? emptyStateShellClass : "h-full"
      )}>
        <div className={emptyStateIconShellClass}>
          <Activity className={COLORS.neutral.light.textLight} size={40} />
        </div>
        <h4 className={emptyStateTitleClass}>
          暂无报告
        </h4>
        <p className={emptyStateBodyClass}>
          完成体态评估后，报告将在此显示
        </p>
      </div>
    );
  }

  // 内嵌模式
  if (inline) {
    return (
      <div className={cn("flex-1 flex flex-col min-h-0", className)}>
        <Header />
        
        <div className={inlineReportShellClass}>
          <MarkdownReport 
            content={currentContent} 
            animate={true} 
            className="border-none rounded-none h-full bg-transparent" 
          />
        </div>

        {onReset && (
          <div className="mt-6 flex gap-4">
            <button 
              onClick={onReset}
              className={resetButtonClass}
            >
              <RotateCcw size={16} />
              重新评估
            </button>
          </div>
        )}
      </div>
    );
  }

  // 弹窗模式
  return (
    <div className={cn(
      modalShellClass,
      isFullscreen 
        ? "w-full h-full rounded-none" 
        : "w-full max-w-5xl h-[90vh] rounded-[2.5rem] animate-in zoom-in-95 duration-300",
      className
    )}>
      <Header />
      
      <div className={modalBodyClass}>
        <MarkdownReport 
          content={currentContent} 
          animate={false} 
          className="border-none rounded-none h-full" 
        />
      </div>
    </div>
  );
};

export default PostureReportViewer;

import React, { useMemo } from 'react';
import {
  Activity,
  Calendar,
  ChevronRight,
  Clock,
  FileText,
  TrendingDown,
  TrendingUp,
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { useAssessmentRecordStore } from '../../store/useAssessmentRecordStore';
import { useTreatmentPlanStore } from '../../store/useTreatmentPlanStore';
import { Badge } from '../ui/Badge';
import { Button } from '../ui/Button';
import { Card, CardContent, CardHeader, CardTitle } from '../ui/Card';

export const TreatmentTimeline: React.FC = () => {
  const { records, setCurrentRecord } = useAssessmentRecordStore();
  const { versions, setCurrentVersion } = useTreatmentPlanStore();

  const timelineData = useMemo(() => {
    const assessmentRecords = records.map((record) => ({
      id: record.id,
      timestamp: record.timestamp,
      type: 'assessment' as const,
      data: record,
    }));

    const treatmentRecords = versions.map((version) => ({
      id: version.id,
      timestamp: version.createdAt,
      type: 'treatment' as const,
      data: version,
    }));

    return [...assessmentRecords, ...treatmentRecords].sort(
      (a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime(),
    );
  }, [records, versions]);

  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    return date.toLocaleString('zh-CN', {
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  const formatFullDate = (dateString: string) => {
    const date = new Date(dateString);
    return date.toLocaleString('zh-CN', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  const getRecordIcon = (type: string) => {
    switch (type) {
      case 'assessment':
        return <Activity className="h-5 w-5" />;
      case 'treatment':
        return <FileText className="h-5 w-5" />;
      default:
        return <Clock className="h-5 w-5" />;
    }
  };

  const getRecordTypeLabel = (type: string) => {
    switch (type) {
      case 'assessment':
        return '评估';
      case 'treatment':
        return '治疗计划';
      default:
        return '记录';
    }
  };

  const getAssessmentTypeLabel = (type: string) => {
    const labels = {
      front: '正面',
      side: '侧面',
      back: '背面',
    };
    return labels[type as keyof typeof labels] || type;
  };

  const getImprovementBadge = (record: any) => {
    if (record.type !== 'assessment') return null;

    const improvement = record.data.improvement;
    if (improvement === undefined) return null;

    if (improvement > 0) {
      return (
        <Badge variant="success" className="flex items-center gap-1">
          <TrendingUp className="h-3 w-3" />
          改善 {improvement}%
        </Badge>
      );
    }

    if (improvement < 0) {
      return (
        <Badge variant="warning" className="flex items-center gap-1">
          <TrendingDown className="h-3 w-3" />
          下降 {Math.abs(improvement)}%
        </Badge>
      );
    }

    return null;
  };

  const handleViewDetails = (record: any) => {
    if (record.type === 'assessment') {
      setCurrentRecord(record.id);
    } else if (record.type === 'treatment') {
      setCurrentVersion(record.id);
    }
  };

  const recordShellClass = 'rounded-20 border border-slate-200 bg-white p-4 transition-shadow hover:shadow-[0_8px_20px_rgba(15,23,42,0.08)]';

  return (
    <Card className="w-full">
      <CardHeader>
        <CardTitle>治疗时间线</CardTitle>
      </CardHeader>
      <CardContent>
        {timelineData.length === 0 ? (
          <div className="state-panel">
            <Calendar className="mx-auto mb-4 h-16 w-16 opacity-50" />
            <p>暂无治疗记录</p>
            <p className="mt-2 text-sm">开始评估和治疗后，这里会显示完整的时间线。</p>
          </div>
        ) : (
          <div className="relative">
            <div className="absolute bottom-0 left-4 top-0 w-0.5 bg-slate-200" />

            <div className="space-y-6">
              {timelineData.map((record) => (
                <div key={record.id} className="relative pl-12">
                  <div className="absolute left-2 h-4 w-4 rounded-full border-2 border-white bg-blue-500 shadow" />

                  <div className={recordShellClass}>
                    <div className="mb-3 flex items-start justify-between">
                      <div className="flex items-center gap-3">
                        <div
                          className={cn(
                            'rounded-lg p-2',
                            record.type === 'assessment'
                              ? 'bg-blue-100 text-blue-600'
                              : 'bg-emerald-100 text-emerald-600',
                          )}
                        >
                          {getRecordIcon(record.type)}
                        </div>
                        <div>
                          <div className="flex items-center gap-2">
                            <h3 className="font-semibold text-slate-900">{getRecordTypeLabel(record.type)}</h3>
                            <Badge variant="info">{formatDate(record.timestamp)}</Badge>
                          </div>
                          <p className="text-sm text-slate-600">{formatFullDate(record.timestamp)}</p>
                        </div>
                      </div>

                      <Button variant="ghost" size="sm" onClick={() => handleViewDetails(record)}>
                        <ChevronRight className="h-4 w-4" />
                      </Button>
                    </div>

                    {record.type === 'assessment' ? (
                      <div className="space-y-3">
                        <div className="flex items-center gap-2">
                          <Badge variant="default">{getAssessmentTypeLabel(record.data.assessmentType)}</Badge>
                          {getImprovementBadge(record)}
                        </div>

                        {record.data.imageData ? (
                          <div className="aspect-video overflow-hidden rounded-xl bg-slate-100">
                            <img
                              src={record.data.imageData}
                              alt={`评估图像 - ${record.id}`}
                              className="h-full w-full object-cover"
                            />
                          </div>
                        ) : null}

                        {record.data.metrics && Object.keys(record.data.metrics).length > 0 ? (
                          <div className="grid grid-cols-2 gap-2 md:grid-cols-4">
                            {Object.entries(record.data.metrics).slice(0, 4).map(([key, value]) => (
                              <div key={key} className="rounded-xl bg-slate-50 p-2">
                                <p className="text-xs text-slate-600">{key}</p>
                                <p className="text-sm font-semibold">
                                  {typeof value === 'number' ? value.toFixed(2) : value}
                                </p>
                              </div>
                            ))}
                          </div>
                        ) : null}

                        {record.data.feedback ? (
                          <div className="semantic-panel-soft semantic-panel-soft-info">
                            <p className="text-sm text-slate-700">
                              <strong>反馈：</strong>
                              {record.data.feedback}
                            </p>
                          </div>
                        ) : null}
                      </div>
                    ) : (
                      <div className="space-y-3">
                        <div className="flex items-center gap-2">
                          <Badge variant="success">版本 {record.data.version}</Badge>
                          {record.data.isCurrent ? <Badge variant="primary">当前版本</Badge> : null}
                        </div>

                        {record.data.tags?.length ? (
                          <div className="flex flex-wrap gap-1">
                            {record.data.tags.map((tag: string, tagIndex: number) => (
                              <Badge key={`${tag}-${tagIndex}`} variant="default" className="text-xs">
                                {tag}
                              </Badge>
                            ))}
                          </div>
                        ) : null}

                        <div className="semantic-panel-soft semantic-panel-soft-success">
                          <p className="line-clamp-3 text-sm text-slate-700">
                            {record.data.content.substring(0, 200)}
                            {record.data.content.length > 200 ? '...' : ''}
                          </p>
                        </div>

                        {record.data.assessmentId ? (
                          <div className="text-xs text-slate-500">
                            关联评估 ID: {record.data.assessmentId}
                          </div>
                        ) : null}
                      </div>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
};

