import React, { useMemo } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, ReferenceLine } from 'recharts';
import { TrendData } from '@/types/comparison';

interface TrendChartProps {
  data: TrendData[];
  metricKey: string;
  metricLabel: string;
  unit?: string;
  color?: string;
  showAverage?: boolean;
}

export const TrendChart: React.FC<TrendChartProps> = ({
  data,
  metricKey,
  metricLabel,
  unit = '',
  color = '#3b82f6',
  showAverage = true
}) => {
  // 使用 useMemo 缓存图表数据计算
  const chartData = useMemo(() => {
    return data
      .filter(d => d.metrics[metricKey] !== undefined && !isNaN(d.metrics[metricKey]))
      .map(d => ({
        date: d.date,
        value: Number(d.metrics[metricKey]),
        timestamp: d.timestamp
      }));
  }, [data, metricKey]);

  // 计算平均值
  const average = useMemo(() => {
    if (chartData.length === 0) return 0;
    const sum = chartData.reduce((acc, d) => acc + d.value, 0);
    return sum / chartData.length;
  }, [chartData]);

  // 计算趋势
  const trend = useMemo(() => {
    if (chartData.length < 2) return 'stable';
    const first = chartData[0].value;
    const last = chartData[chartData.length - 1].value;
    const change = ((last - first) / Math.abs(first)) * 100;
    
    if (change > 10) return 'up';
    if (change < -10) return 'down';
    return 'stable';
  }, [chartData]);

  if (chartData.length === 0) {
    return (
      <div className="w-full h-64 flex items-center justify-center bg-slate-50 rounded-2xl border border-slate-100">
        <div className="text-center">
          <div className="text-slate-400 text-sm mb-2">暂无数据</div>
          <div className="text-slate-300 text-xs">该指标在历史评估中未记录</div>
        </div>
      </div>
    );
  }

  // 如果数据点过多，进行采样
  const sampledData = useMemo(() => {
    const maxPoints = 20;
    if (chartData.length <= maxPoints) return chartData;
    
    const step = Math.ceil(chartData.length / maxPoints);
    return chartData.filter((_, index) => index % step === 0);
  }, [chartData]);

  return (
    <div className="w-full h-64 p-4 bg-slate-50 rounded-2xl border border-slate-100">
      {/* 标题和统计信息 */}
      <div className="flex items-center justify-between mb-4">
        <div>
          <h4 className="text-xs font-black text-slate-900 uppercase tracking-widest">
            {metricLabel} 趋势
          </h4>
          <div className="flex items-center gap-2 mt-1">
            <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
              单位: {unit}
            </span>
            {chartData.length > 0 && (
              <span className="text-[10px] font-medium text-slate-500">
                共 {chartData.length} 次评估
              </span>
            )}
          </div>
        </div>
        
        {/* 趋势指示器 */}
        <div className="flex items-center gap-2">
          <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
            趋势
          </span>
          <span className={`
            text-xs font-black px-2 py-1 rounded-lg
            ${trend === 'up' ? 'bg-emerald-100 text-emerald-700' :
              trend === 'down' ? 'bg-rose-100 text-rose-700' :
              'bg-slate-200 text-slate-600'}
          `}>
            {trend === 'up' ? '↑ 上升' :
             trend === 'down' ? '↓ 下降' :
             '→ 稳定'}
          </span>
        </div>
      </div>

      {/* 图表 */}
      <ResponsiveContainer width="100%" height="100%">
        <LineChart data={sampledData} margin={{ top: 5, right: 5, left: -20, bottom: 5 }}>
          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
          <XAxis 
            dataKey="date" 
            tick={{ fontSize: 10, fill: '#94a3b8' }}
            stroke="#e2e8f0"
            tickLine={false}
            axisLine={false}
          />
          <YAxis 
            tick={{ fontSize: 10, fill: '#94a3b8' }}
            stroke="#e2e8f0"
            tickLine={false}
            axisLine={false}
            domain={['auto', 'auto']}
          />
          <Tooltip 
            contentStyle={{ 
              backgroundColor: 'white', 
              border: '1px solid #e2e8f0',
              borderRadius: '8px',
              fontSize: '12px',
              boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)'
            }}
            formatter={(value: number) => [`${value} ${unit}`, metricLabel]}
            labelFormatter={(label) => `日期: ${label}`}
          />
          {showAverage && chartData.length > 1 && (
            <ReferenceLine 
              y={average} 
              stroke="#94a3b8" 
              strokeDasharray="5 5"
              strokeWidth={1}
            />
          )}
          <Line 
            type="monotone" 
            dataKey="value" 
            stroke={color} 
            strokeWidth={2}
            dot={{ fill: color, strokeWidth: 2, r: 3, stroke: '#fff' }}
            activeDot={{ r: 5, strokeWidth: 0 }}
            animationDuration={500}
            animationEasing="ease-out"
          />
        </LineChart>
      </ResponsiveContainer>

      {/* 统计信息 */}
      {chartData.length > 0 && (
        <div className="mt-2 pt-2 border-t border-slate-200/50 flex items-center justify-between text-[10px] text-slate-400">
          <span>首次: {chartData[0].value} {unit}</span>
          <span>平均: {average.toFixed(1)} {unit}</span>
          <span>最新: {chartData[chartData.length - 1].value} {unit}</span>
        </div>
      )}
    </div>
  );
};

// 虚拟滚动版本（用于大数据量）
interface VirtualTrendChartProps extends TrendChartProps {
  containerHeight?: number;
}

export const VirtualTrendChart: React.FC<VirtualTrendChartProps> = ({
  data,
  containerHeight = 600,
  ...props
}) => {
  // 如果数据量不大，使用普通版本
  if (data.length <= 10) {
    return <TrendChart data={data} {...props} />;
  }

  // 大数据量时，只显示最近 10 条
  const recentData = useMemo(() => {
    return data.slice(-10);
  }, [data]);

  return (
    <div>
      <TrendChart data={recentData} {...props} />
      <div className="mt-2 text-center text-xs text-slate-400">
        显示最近 10 次评估（共 {data.length} 次）
      </div>
    </div>
  );
};

import React, { useEffect, useMemo, useRef, useState } from 'react';
import { AlertTriangle, Ban, Check, Clock, Copy, Key, RotateCw, ShieldCheck, X } from 'lucide-react';
import { Button, Card } from '@/components/ui';
import type { Patient } from '@/types/patient';
import { IntegrationService, type FamilyAccessLink } from '@/services/integrationService';
import { getPatientDisplayName } from '@/lib/patient-utils';
import { cn } from '@/lib/utils';

interface FamilyAccessManagerProps {
  patient: Patient;
}

const getStatusLabel = (link: FamilyAccessLink) => {
  if (link.status === 'revoked') return '已撤销';
  if (link.is_expired) return '已过期';
  if (link.status === 'active') return '有效';
  return link.status;
};

export const FamilyAccessManager: React.FC<FamilyAccessManagerProps> = ({ patient }) => {
  const [links, setLinks] = useState<FamilyAccessLink[]>([]);
  const [familyCode, setFamilyCode] = useState('');
  const [issuedCode, setIssuedCode] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [actionLoading, setActionLoading] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);

  // 防止同一患者重复自动生成
  const autoGeneratedRef = useRef<string | null>(null);

  const activeLink = useMemo(
    () => links.find((link) => link.status === 'active' && !link.is_expired),
    [links]
  );

  const syncAndLoad = async () => {
    setLoading(true);
    setError(null);
    try {
      // 1. 确保患者存在于 Python 后端（不限来源：手动/筛查/导入）
      await IntegrationService.ensurePatient({
        patient_id: patient.id,
        display_name: patient.name,
        patient_code: patient.shortCode,
        short_code: patient.shortCode,
      });

      // 2. 拉取家庭码状态
      const data = await IntegrationService.listFamilyAccess(patient.id);
      setLinks(data);

      // 3. 无有效码且未自动生成过 → 自动生成
      const hasActive = data.some(
        (link) => link.status === 'active' && !link.is_expired
      );
      if (!hasActive && autoGeneratedRef.current !== patient.id) {
        autoGeneratedRef.current = patient.id;
        const result = await IntegrationService.rotateFamilyAccess(patient.id, {
          family_code: null, // 自动生成随机码
          expires_at: null,
          linked_to: getPatientDisplayName(patient),
        });
        setIssuedCode(result.family_code);
        // 重新拉取列表
        const refreshed = await IntegrationService.listFamilyAccess(patient.id);
        setLinks(refreshed);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : '家庭码状态读取失败');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    syncAndLoad();
  }, [patient.id]);

  const handleRotate = async () => {
    setActionLoading('rotate');
    setError(null);
    setIssuedCode(null);
    try {
      const result = await IntegrationService.rotateFamilyAccess(patient.id, {
        family_code: familyCode.trim() || null,
        expires_at: null,
        linked_to: getPatientDisplayName(patient),
      });
      setIssuedCode(result.family_code);
      setFamilyCode('');
      await syncAndLoad();
    } catch (err) {
      setError(err instanceof Error ? err.message : '家庭码轮换失败');
    } finally {
      setActionLoading(null);
    }
  };

  const handleRevoke = async (linkId: number) => {
    setActionLoading(`revoke-${linkId}`);
    setError(null);
    try {
      await IntegrationService.revokeFamilyAccess(linkId);
      await syncAndLoad();
    } catch (err) {
      setError(err instanceof Error ? err.message : '家庭码撤销失败');
    } finally {
      setActionLoading(null);
    }
  };

  const handleMakePermanent = async (linkId: number) => {
    setActionLoading(`extend-${linkId}`);
    setError(null);
    try {
      await IntegrationService.extendFamilyAccess(linkId, null);
      await syncAndLoad();
    } catch (err) {
      setError(err instanceof Error ? err.message : '家庭码设为长期失败');
    } finally {
      setActionLoading(null);
    }
  };

  const handleCopy = async () => {
    if (!issuedCode) return;
    await navigator.clipboard.writeText(issuedCode);
    setCopied(true);
    window.setTimeout(() => setCopied(false), 1200);
  };

  return (
    <Card variant="default" padding="lg" className="border-slate-200 bg-white/95 shadow-[0_12px_36px_rgba(15,23,42,0.06)]">
      {/* 家庭码展示横幅（自动生成或手动轮换后显示） */}
      {issuedCode && (
        <div className="mb-4 flex items-center gap-3 rounded-xl border border-emerald-200 bg-emerald-50/90 p-3.5 shadow-sm">
          <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-emerald-100 text-emerald-700">
            <Key size={18} />
          </div>
          <div className="flex-1 min-w-0">
            <p className="text-xs font-semibold text-emerald-800">家庭码，请告知家长在小柱端输入</p>
            <p className="mt-0.5 font-mono text-lg font-bold tracking-[0.2em] text-emerald-900">{issuedCode}</p>
          </div>
          <Button
            variant="secondary"
            size="sm"
            icon={copied ? <Check size={14} /> : <Copy size={14} />}
            onClick={handleCopy}
          >
            {copied ? '已复制' : '复制'}
          </Button>
          <button onClick={() => setIssuedCode(null)} className="text-slate-400 hover:text-slate-600">
            <X size={16} />
          </button>
        </div>
      )}

      <div className="flex flex-col gap-4 xl:flex-row xl:items-start xl:justify-between">
        <div className="min-w-0">
          <div className="flex items-center gap-2">
            <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-emerald-50 text-emerald-700">
              <ShieldCheck size={18} />
            </div>
            <div>
              <h3 className="text-base font-semibold text-slate-900">家庭码安全管理</h3>
              <p className="text-xs text-slate-500">家庭码默认长期有效；只有遗失、泄露或家长更换时才手动重置。服务端仅保存不可逆哈希。</p>
            </div>
          </div>
          {activeLink ? (
            <div className="mt-3 inline-flex items-center gap-2 rounded-full border border-emerald-200 bg-emerald-50 px-3 py-1 text-xs font-medium text-emerald-700">
              <Check size={13} />
              当前存在有效家庭码
            </div>
          ) : (
            <div className="mt-3 inline-flex items-center gap-2 rounded-full border border-amber-200 bg-amber-50 px-3 py-1 text-xs font-medium text-amber-700">
              <AlertTriangle size={13} />
              当前无有效家庭码
            </div>
          )}
        </div>

        <div className="flex w-full flex-col gap-3 xl:max-w-[520px]">
          <div className="grid gap-2 sm:grid-cols-[1fr_auto]">
            <input
              value={familyCode}
              onChange={(event) => setFamilyCode(event.target.value.toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 6))}
              placeholder="留空自动生成"
              className="h-10 rounded-xl border border-slate-200 bg-white px-3 text-sm font-semibold tracking-widest text-slate-900 outline-none transition focus:border-emerald-500"
            />
            <Button
              variant="primary"
              size="md"
              icon={activeLink ? <RotateCw size={16} /> : <ShieldCheck size={16} />}
              loading={actionLoading === 'rotate'}
              onClick={handleRotate}
            >
              {activeLink ? '重置家庭码' : '生成家庭码'}
            </Button>
          </div>
          <p className="text-[11px] leading-5 text-slate-500">
            不需要定期更换家庭码。重置会立即撤销旧码并生成新码，适用于旧码泄露、丢失或绑定家庭变更。
          </p>

          {error && (
            <div className="rounded-xl border border-red-200 bg-red-50 px-3 py-2 text-xs text-red-700">{error}</div>
          )}
        </div>
      </div>

      <div className="mt-5 overflow-x-auto rounded-xl border border-slate-200">
        <div className="min-w-[680px]">
          <div className="grid grid-cols-[88px_1fr_1fr_160px] bg-slate-50 px-3 py-2 text-xs font-semibold text-slate-500">
            <span>状态</span>
            <span>绑定对象</span>
            <span>有效期</span>
            <span className="text-right">操作</span>
          </div>
          {loading ? (
            <div className="flex items-center gap-2 px-3 py-4 text-sm text-slate-500">
              <RotateCw className="animate-spin" size={15} />
              正在读取家庭码状态
            </div>
          ) : links.length === 0 ? (
            <div className="px-3 py-4 text-sm text-slate-500">暂无家庭码记录</div>
          ) : (
            links.map((link) => {
              const label = getStatusLabel(link);
              const canRevoke = link.status === 'active' && !link.is_expired;
              return (
                <div key={link.id} className="grid grid-cols-[88px_1fr_1fr_160px] items-center border-t border-slate-100 px-3 py-2 text-sm">
                  <span
                    className={cn(
                      'w-fit rounded-full px-2 py-0.5 text-xs font-semibold',
                      label === '有效' && 'bg-emerald-50 text-emerald-700',
                      label === '已过期' && 'bg-amber-50 text-amber-700',
                      label === '已撤销' && 'bg-slate-100 text-slate-500'
                    )}
                  >
                    {label}
                  </span>
                  <span className="truncate text-slate-700">{link.linked_to || getPatientDisplayName(patient)}</span>
                  <span className="flex items-center gap-1 text-xs text-slate-500">
                    <Clock size={13} />
                    {link.expires_at ? new Date(link.expires_at).toLocaleString() : '长期有效'}
                  </span>
                  <div className="flex justify-end gap-2">
                    {link.expires_at && (
                      <Button
                        variant="secondary"
                        size="sm"
                        icon={<Clock size={14} />}
                        loading={actionLoading === `extend-${link.id}`}
                        disabled={link.status === 'revoked'}
                        onClick={() => handleMakePermanent(link.id)}
                      >
                        设长期
                      </Button>
                    )}
                    <Button
                      variant="danger"
                      size="sm"
                      icon={<Ban size={14} />}
                      loading={actionLoading === `revoke-${link.id}`}
                      disabled={!canRevoke}
                      onClick={() => handleRevoke(link.id)}
                    >
                      撤销
                    </Button>
                  </div>
                </div>
              );
            })
          )}
        </div>
      </div>
    </Card>
  );
};

/** Data and types extracted from ParentPushCenter.tsx. */

import type { ScaleAssessmentData } from '@/types/assessment';
import type { Patient } from '@/types/patient';

// ── Scale options ──

export type ScaleAdminLevel = 'parent' | 'parent_adapted' | 'clinician_only';

export const SCALE_OPTIONS: { id: string; name: string; desc: string; adminLevel: ScaleAdminLevel; levelNote: string }[] = [
  { id: 'SRS-22', name: 'SRS-22 脊柱侧弯问卷', desc: '功能/疼痛/自我形象/精神健康/满意度', adminLevel: 'parent', levelNote: '患者自评量表（PROM），适合家长端填写' },
  { id: 'ODI',   name: 'ODI 功能障碍指数',    desc: '下背痛日常活动障碍评估',           adminLevel: 'parent', levelNote: '患者自评量表（PROM），适合家长端填写' },
  { id: 'VAS',   name: 'VAS 视觉模拟疼痛评分', desc: '疼痛强度快速评估',                 adminLevel: 'parent', levelNote: '简单直观，家长可独立完成' },
];

// ── Plan template ──

export const PLAN_TEMPLATE = `# 个人化脊柱侧弯康复训练方案

## 训练原则
- Schroth 三维脊柱侧弯矫正体操
- 重点矫正（待填写）侧凸
- 配合旋转呼吸训练
- 每天坚持，循序渐进

## 热身（5分钟）
- 猫牛式：缓慢进行，配合呼吸，10次
- 骨盆前后倾：激活核心肌群，10次
- 肩胛骨回缩：改善驼背姿势，10次

## 核心训练（15分钟）
- 侧平板支撑：增强核心力量，3组×30秒
- 死虫式：核心稳定训练，3组×10次
- Schroth旋转呼吸：在矫正位进行深呼吸，5分钟

## 拉伸放松（10分钟）
- 胸椎凹侧拉伸：针对性拉伸，3组×30秒
- 胸肌拉伸：改善前侧紧张，2组×30秒
- 儿童式放松：结束放松，2分钟

## 注意事项
1. 训练时穿着舒适运动服
2. 训练前确保支具已取下
3. 如出现疼痛立即停止，联系康复师
4. 每天记录训练完成情况`;

// ── Types (component-internal) ──

export interface AssessmentInfo {
  exists: boolean; riskLabel?: string; summaryText?: string; createdAt?: string;
}

export interface PlanInfo {
  exists: boolean; planId?: string; content?: string; status?: string; createdAt?: string;
}

export interface ScaleInfo {
  taskId: string; scaleId: string; sessionId: string; status: string;
  createdAt: string; submittedAt?: string | null; scaleData?: ScaleAssessmentData | null;
}

export interface TrackingRecord {
  tracking_date: string; total_duration_min: number;
  exercises_completed: Array<{ name: string; duration: number; completed: boolean }>;
  symptoms: Record<string, any>; notes: string;
}

export interface ParentPushCenterProps {
  patient: Patient; sessionId?: string | null; therapistName?: string;
}

import React, { useEffect, useState, useCallback } from 'react';
import {
  Send, FileText, ClipboardList, Dumbbell,
  Check, AlertCircle, RotateCw, ChevronDown, ChevronUp,
  Clock, TrendingUp, Activity, AlertTriangle, Bell,
} from 'lucide-react';
import { Button, Card } from '@/components/ui';
import {
  IntegrationService,
  type ParentReportResult,
  type PatientReminders,
  type ReminderItem,
  SCALE_INTERVALS,
} from '@/services/integrationService';
import { cn } from '@/lib/utils';
import {
  SCALE_OPTIONS, PLAN_TEMPLATE,
  type AssessmentInfo, type PlanInfo, type ScaleInfo,
  type TrackingRecord, type ParentPushCenterProps,
} from './ParentPushCenter.data';

export const ParentPushCenter: React.FC<ParentPushCenterProps> = ({
  patient,
  sessionId,
  therapistName = '康复师',
}) => {
  // ── State ──
  const [assessment, setAssessment] = useState<AssessmentInfo>({ exists: false });
  const [plan, setPlan] = useState<PlanInfo>({ exists: false });
  const [scales, setScales] = useState<ScaleInfo[]>([]);
  const [tracking, setTracking] = useState<TrackingRecord[]>([]);
  const [parentReports, setParentReports] = useState<ParentReportResult[]>([]);
  const [reminders, setReminders] = useState<PatientReminders | null>(null);

  const [planEditorOpen, setPlanEditorOpen] = useState(false);
  const [planContent, setPlanContent] = useState(PLAN_TEMPLATE);
  const [selectedScale, setSelectedScale] = useState<string>('SRS-22');
  const [feedbackOpen, setFeedbackOpen] = useState(false);

  const [loading, setLoading] = useState(true);
  const [actionLoading, setActionLoading] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [successMsg, setSuccessMsg] = useState<string | null>(null);

  // ── Load all data ──

  const loadAll = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const [ast, plans, scaleResults, trackingData, parentReportData, reminderData] = await Promise.all([
        IntegrationService.getAssessmentSummary(patient.id),
        IntegrationService.getTreatmentPlans(patient.id),
        IntegrationService.getScaleResultsByPatient(patient.id),
        IntegrationService.getTrackingHistory(patient.id),
        IntegrationService.getParentReports(patient.id),
        IntegrationService.getReminders(patient.id).catch(() => null),
      ]);

      setAssessment(ast ? {
        exists: true,
        riskLabel: ast.risk_label,
        summaryText: ast.summary_text,
        createdAt: ast.created_at,
      } : { exists: false });

      const latestPlan = plans[0];
      setPlan(latestPlan ? {
        exists: true,
        planId: latestPlan.plan_id,
        content: latestPlan.plan_content,
        status: latestPlan.status,
        createdAt: latestPlan.created_at,
      } : { exists: false });

      setScales(scaleResults.map(s => ({
        taskId: s.task_id,
        scaleId: s.scale_id,
        sessionId: s.session_id,
        status: s.status,
        createdAt: s.created_at,
        submittedAt: s.submitted_at,
        scaleData: s.scale_data,
      })));

      setTracking(trackingData.slice(0, 7)); // 最近7天
      setParentReports(parentReportData);
      setReminders(reminderData);
    } catch (err) {
      setError(err instanceof Error ? err.message : '加载失败');
    } finally {
      setLoading(false);
    }
  }, [patient.id]);

  useEffect(() => {
    loadAll();
  }, [loadAll]);

  // ── Push actions ──

  const handlePushPlan = async () => {
    setActionLoading('plan');
    setError(null);
    setSuccessMsg(null);
    try {
      await IntegrationService.pushTreatmentPlan({
        patient_id: patient.id,
        patient_name: patient.name || patient.id,
        session_id: sessionId || `manual_${Date.now()}`,
        therapist_name: therapistName,
        plan_content: planContent,
      });
      setSuccessMsg('训练处方已推送至家长端');
      setPlanEditorOpen(false);
      await loadAll();
    } catch (err) {
      setError(err instanceof Error ? err.message : '推送失败');
    } finally {
      setActionLoading(null);
    }
  };

  const handlePushScale = async () => {
    setActionLoading('scale');
    setError(null);
    setSuccessMsg(null);
    try {
      await IntegrationService.pushScaleTask({
        patient_id: patient.id,
        patient_name: patient.name || patient.id,
        session_id: sessionId || `manual_${Date.now()}`,
        scale_id: selectedScale as 'SRS-22' | 'ODI' | 'VAS',
        therapist_name: therapistName,
      });
      setSuccessMsg(`${selectedScale} 量表已推送至家长端`);
      await loadAll();
    } catch (err) {
      setError(err instanceof Error ? err.message : '推送失败');
    } finally {
      setActionLoading(null);
    }
  };

  // ── Reminder helpers ──

  const getReminderFor = (itemType: string, itemId: string): ReminderItem | undefined => {
    return reminders?.items.find(it => it.item_type === itemType && it.item_id === itemId);
  };

  const getScaleReminder = (scaleId: string): ReminderItem | undefined => {
    return getReminderFor('scale', scaleId);
  };

  const planReminder = getReminderFor('plan', 'treatment_plan');
  const assessmentReminder = getReminderFor('assessment', 'assessment_summary');

  // ── Derived ──

  const trackingSummary = tracking.length > 0 ? (() => {
    const completedDays = tracking.filter(t => t.total_duration_min > 0).length;
    const avgPain = tracking.reduce((sum, t) => sum + (t.symptoms?.pain_level || 0), 0) / tracking.length;
    return { completedDays, total: tracking.length, avgPain: avgPain.toFixed(1) };
  })() : null;
  const pendingScaleCount = scales.filter(s => s.status === 'pending').length;
  const completedScaleCount = scales.filter(s => s.status === 'completed').length;
  const latestParentReport = parentReports[0];
  const totalOverdue = reminders?.overdue_count ?? 0;
  const totalDueSoon = reminders?.due_soon_count ?? 0;

  // ── Render ──

  return (
    <Card variant="default" padding="lg" className="border-slate-200 bg-white/95 shadow-[0_12px_36px_rgba(15,23,42,0.06)]">
      {/* Header */}
      <div className="flex items-center gap-2 mb-5">
        <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-violet-50 text-violet-700">
          <Send size={18} />
        </div>
        <div className="flex-1">
          <h3 className="text-base font-semibold text-slate-900">推送至家长端</h3>
          <p className="text-xs text-slate-500">评估摘要、训练处方、量表处方一键推送到小柱家长端</p>
        </div>
        {reminders && (totalOverdue > 0 || totalDueSoon > 0) && (
          <div className="flex items-center gap-1.5">
            {totalOverdue > 0 && (
              <span className="inline-flex items-center gap-1 rounded-full bg-red-50 px-2.5 py-1 text-xs font-semibold text-red-700">
                <AlertCircle size={12} />
                {totalOverdue} 项逾期
              </span>
            )}
            {totalDueSoon > 0 && (
              <span className="inline-flex items-center gap-1 rounded-full bg-amber-50 px-2.5 py-1 text-xs font-semibold text-amber-700">
                <AlertTriangle size={12} />
                {totalDueSoon} 项临近
              </span>
            )}
          </div>
        )}
      </div>

      {loading ? (
        <div className="flex items-center gap-2 py-4 text-sm text-slate-500">
          <RotateCw className="animate-spin" size={15} />
          正在加载推送状态...
        </div>
      ) : (
        <div className="space-y-4">
          {/* ── 评估摘要 ── */}
          <PushRow
            icon={<FileText size={16} />}
            label="评估摘要"
            done={assessment.exists}
            doneText={assessment.riskLabel || '已推送'}
            doneSub={assessment.createdAt ? `推送于 ${new Date(assessment.createdAt).toLocaleDateString()}` : ''}
            pendingText="完成接诊评估后将自动推送"
            reminder={assessmentReminder}
          />

          {/* ── 训练处方 ── */}
          <div className="rounded-xl border border-slate-100 p-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2.5">
                <Dumbbell size={16} className="text-slate-500" />
                <div>
                  <span className="text-sm font-semibold text-slate-800">训练处方</span>
                  {plan.exists && (
                    <span className="ml-2 inline-flex items-center rounded-full bg-emerald-50 px-2 py-0.5 text-xs font-medium text-emerald-700">
                      <Check size={11} className="mr-1" />已推送
                    </span>
                  )}
                  <ReminderBadge reminder={planReminder} />
                </div>
              </div>
              <Button
                variant={plan.exists ? 'secondary' : 'primary'}
                size="sm"
                icon={plan.exists ? <FileText size={14} /> : <Send size={14} />}
                onClick={() => {
                  setPlanContent(plan.content || PLAN_TEMPLATE);
                  setPlanEditorOpen(!planEditorOpen);
                }}
              >
                {plan.exists ? '查看/更新' : '编辑处方'}
              </Button>
            </div>

            {/* Plan editor (expandable) */}
            {planEditorOpen && (
              <div className="mt-3 space-y-3">
                <textarea
                  value={planContent}
                  onChange={(e) => setPlanContent(e.target.value)}
                  rows={12}
                  className="w-full rounded-xl border border-slate-200 bg-slate-50 p-3 text-sm font-mono text-slate-700 outline-none focus:border-violet-400 resize-y"
                  placeholder="输入 Markdown 格式的训练处方..."
                />
                <div className="flex items-center justify-end gap-2">
                  <Button variant="secondary" size="sm" onClick={() => setPlanEditorOpen(false)}>
                    取消
                  </Button>
                  <Button
                    variant="primary"
                    size="sm"
                    icon={<Send size={14} />}
                    loading={actionLoading === 'plan'}
                    onClick={handlePushPlan}
                  >
                    推送至家长端
                  </Button>
                </div>
              </div>
            )}

            {plan.exists && !planEditorOpen && plan.content && (
              <div className="mt-2 text-xs text-slate-500 line-clamp-2">
                {plan.content.slice(0, 120).replace(/#/g, '')}...
              </div>
            )}
          </div>

          {/* ── 量表处方 ── */}
          <div className="rounded-xl border border-slate-100 p-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2.5">
                <ClipboardList size={16} className="text-slate-500" />
                <div>
                  <span className="text-sm font-semibold text-slate-800">量表处方</span>
                  {pendingScaleCount > 0 && (
                    <span className="ml-2 inline-flex items-center rounded-full bg-amber-50 px-2 py-0.5 text-xs font-medium text-amber-700">
                      {pendingScaleCount} 份待填写
                    </span>
                  )}
                  {completedScaleCount > 0 && (
                    <span className="ml-2 inline-flex items-center rounded-full bg-emerald-50 px-2 py-0.5 text-xs font-medium text-emerald-700">
                      {completedScaleCount} 份已回传
                    </span>
                  )}
                </div>
              </div>
              <div className="flex items-center gap-2">
                <select
                  value={selectedScale}
                  onChange={(e) => setSelectedScale(e.target.value)}
                  className="h-9 rounded-xl border border-slate-200 bg-white px-3 text-xs font-medium text-slate-700 outline-none"
                >
                  {SCALE_OPTIONS.map(s => (
                    <option key={s.id} value={s.id}>
                      {s.name} — {s.adminLevel === 'parent' ? '🟢 家长自评' : '🟡 适配版'}
                    </option>
                  ))}
                </select>
                <Button
                  variant="primary"
                  size="sm"
                  icon={<Send size={14} />}
                  loading={actionLoading === 'scale'}
                  onClick={handlePushScale}
                >
                  推送
                </Button>
              </div>

              {/* Classification note */}
              <p className="mt-2 text-[11px] text-slate-400 flex items-center gap-1.5">
                <AlertCircle size={12} />
                仅展示可下发给家长的<b className="text-emerald-600">患者自评量表（PROM）</b>类量表。
                Berg/MMT/MAS 等<b className="text-red-500">专业评定</b>类量表需在诊所内由康复师完成。
              </p>
            </div>

            {/* Scale status list */}
            {scales.length > 0 && (
              <div className="mt-2 space-y-1">
                {scales.map(s => {
                  const scaleReminder = getScaleReminder(s.scaleId);
                  return (
                    <div key={s.taskId} className="flex flex-wrap items-center gap-2 text-xs text-slate-500">
                      <span className={cn(
                        'w-1.5 h-1.5 rounded-full',
                        s.status === 'completed' ? 'bg-emerald-400' : 'bg-amber-400'
                      )} />
                      {s.scaleId} — {s.status === 'completed' ? '已完成' : '待填写'}
                      {s.status === 'completed' && s.scaleData?.totalScore !== undefined && (
                        <span className="rounded-full bg-emerald-50 px-2 py-0.5 font-semibold text-emerald-700">
                          {s.scaleData.totalScore}/{s.scaleData.maxScore ?? '-'} 分
                        </span>
                      )}
                      <span className="text-slate-400">· {new Date(s.createdAt).toLocaleDateString()}</span>
                      {s.submittedAt && (
                        <span className="text-emerald-600">回传于 {new Date(s.submittedAt).toLocaleString()}</span>
                      )}
                      {/* 提醒标签 */}
                      {scaleReminder && (scaleReminder.status === 'overdue' || scaleReminder.status === 'due_soon') && (
                        <ReminderBadge reminder={scaleReminder} />
                      )}
                    </div>
                  );
                })}
              </div>
            )}

            {/* 未推送过的量表提醒（从 reminders 中找 missing 或 overdue 的） */}
            {reminders && (
              <div className="mt-2 space-y-1">
                {reminders.items
                  .filter(it => it.item_type === 'scale' && (it.status === 'overdue' || it.status === 'missing'))
                  .filter(it => !scales.some(s => s.scaleId === it.item_id))
                  .map(it => (
                    <div key={it.item_id} className="flex items-center gap-2 text-xs">
                      <span className="w-1.5 h-1.5 rounded-full bg-red-400" />
                      <span className="text-slate-500">{it.item_label}</span>
                      <ReminderBadge reminder={it} />
                    </div>
                  ))}
              </div>
            )}
          </div>

          {/* ── Messages ── */}
          {successMsg && (
            <div className="rounded-xl border border-emerald-200 bg-emerald-50 px-3 py-2 text-xs font-medium text-emerald-700 flex items-center gap-2">
              <Check size={14} />
              {successMsg}
            </div>
          )}
          {error && (
            <div className="rounded-xl border border-red-200 bg-red-50 px-3 py-2 text-xs text-red-700 flex items-center gap-2">
              <AlertCircle size={14} />
              {error}
            </div>
          )}

          {/* ── 家长反馈（可折叠） ── */}
          <div className="border-t border-slate-100 pt-3">
            <button
              onClick={() => setFeedbackOpen(!feedbackOpen)}
              className="flex w-full items-center justify-between text-sm font-medium text-slate-700 hover:text-slate-900 transition-colors"
            >
              <span className="flex items-center gap-2">
                <Activity size={15} />
                家长端反馈数据
                {trackingSummary && (
                  <span className="text-xs text-slate-400 font-normal">
                    ({trackingSummary.completedDays}/{trackingSummary.total}天打卡)
                  </span>
                )}
              </span>
              {feedbackOpen ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
            </button>

            {feedbackOpen && (
              <div className="mt-3 space-y-3">
                {latestParentReport && (
                  <div className="space-y-2 rounded-xl border border-sky-100 bg-sky-50/60 p-3">
                    <div className="flex flex-wrap items-center justify-between gap-2">
                      <div className="flex items-center gap-2 text-xs font-semibold text-sky-800">
                        <FileText size={13} />
                        家长自筛报告
                      </div>
                      <span className="rounded-full bg-white px-2 py-0.5 text-xs font-semibold text-sky-700">
                        {parentReports.length} 份已回传
                      </span>
                    </div>
                    <div className="flex flex-wrap items-center gap-2 text-xs text-slate-600">
                      <span className="font-semibold text-slate-800">
                        {latestParentReport.risk_label || latestParentReport.risk_level || '已提交'}
                      </span>
                      {latestParentReport.payload?.total !== undefined && (
                        <span className="rounded-full bg-white px-2 py-0.5 font-semibold text-sky-700">
                          {latestParentReport.payload.total}/160 分
                        </span>
                      )}
                      <span className="text-slate-400">
                        {new Date(latestParentReport.submitted_at).toLocaleString()}
                      </span>
                    </div>
                    {(latestParentReport.summary_text || latestParentReport.recommendation) && (
                      <p className="text-xs leading-5 text-slate-600">
                        {latestParentReport.summary_text || latestParentReport.recommendation}
                      </p>
                    )}
                  </div>
                )}

                {/* Tracking summary */}
                {trackingSummary ? (
                  <div className="grid grid-cols-3 gap-3">
                    <div className="rounded-xl bg-emerald-50 p-3 text-center">
                      <div className="text-lg font-bold text-emerald-700">{trackingSummary.completedDays}</div>
                      <div className="text-xs text-emerald-600">训练天数</div>
                    </div>
                    <div className="rounded-xl bg-blue-50 p-3 text-center">
                      <div className="text-lg font-bold text-blue-700">{trackingSummary.avgPain}</div>
                      <div className="text-xs text-blue-600">平均疼痛 /10</div>
                    </div>
                    <div className="rounded-xl bg-violet-50 p-3 text-center">
                      <div className="text-lg font-bold text-violet-700">{completedScaleCount}</div>
                      <div className="text-xs text-violet-600">已填量表</div>
                    </div>
                  </div>
                ) : (
                  <p className="text-xs text-slate-400">暂无打卡数据，等待家长开始训练</p>
                )}

                {/* Recent tracking entries */}
                {tracking.length > 0 && (
                  <div className="overflow-hidden rounded-xl border border-slate-200">
                    <div className="grid grid-cols-[1fr_80px_1fr] bg-slate-50 px-3 py-2 text-xs font-semibold text-slate-500">
                      <span>日期</span>
                      <span className="text-center">时长</span>
                      <span>备注</span>
                    </div>
                    {tracking.slice(0, 5).map((t, i) => (
                      <div key={i} className="grid grid-cols-[1fr_80px_1fr] items-center border-t border-slate-100 px-3 py-2 text-xs">
                        <span className="flex items-center gap-1 text-slate-700">
                          <Clock size={11} className="text-slate-400" />
                          {t.tracking_date}
                        </span>
                        <span className="text-center font-medium text-slate-700">{t.total_duration_min} 分钟</span>
                        <span className="truncate text-slate-500">{t.notes || '-'}</span>
                      </div>
                    ))}
                  </div>
                )}

                {/* Scale results */}
                {completedScaleCount > 0 && (
                  <div className="space-y-2 rounded-xl border border-emerald-100 bg-emerald-50/40 p-3">
                    <div className="flex items-center gap-2 text-xs font-semibold text-emerald-800">
                      <TrendingUp size={13} />
                      家长已回传量表
                    </div>
                    {scales.filter(s => s.status === 'completed').map(s => (
                      <div key={s.taskId} className="flex flex-wrap items-center gap-2 text-xs text-slate-600">
                        <span className="font-semibold text-slate-800">{s.scaleId}</span>
                        {s.scaleData?.scaleName && <span>{s.scaleData.scaleName}</span>}
                        {s.scaleData?.totalScore !== undefined && (
                          <span className="rounded-full bg-white px-2 py-0.5 font-semibold text-emerald-700">
                            {s.scaleData.totalScore}/{s.scaleData.maxScore ?? '-'} 分
                          </span>
                        )}
                        {s.submittedAt && <span className="text-slate-400">{new Date(s.submittedAt).toLocaleString()}</span>}
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}
          </div>
        </div>
      )}
    </Card>
  );
};

// ── Helper: ReminderBadge ──

const ReminderBadge: React.FC<{ reminder?: ReminderItem }> = ({ reminder }) => {
  if (!reminder) return null;

  if (reminder.status === 'overdue') {
    return (
      <span className="ml-1.5 inline-flex items-center gap-0.5 rounded-full bg-red-50 px-1.5 py-0.5 text-[11px] font-semibold text-red-700">
        <AlertCircle size={10} />
        {reminder.days_since_last != null
          ? `逾期 ${reminder.days_since_last} 天`
          : '逾期'}
      </span>
    );
  }

  if (reminder.status === 'due_soon') {
    const remaining = reminder.recommended_interval - (reminder.days_since_last ?? 0);
    return (
      <span className="ml-1.5 inline-flex items-center gap-0.5 rounded-full bg-amber-50 px-1.5 py-0.5 text-[11px] font-semibold text-amber-700">
        <AlertTriangle size={10} />
        {remaining > 0 ? `还剩 ${remaining} 天` : '即将到期'}
      </span>
    );
  }

  if (reminder.status === 'missing') {
    return (
      <span className="ml-1.5 inline-flex items-center gap-0.5 rounded-full bg-slate-100 px-1.5 py-0.5 text-[11px] font-medium text-slate-500">
        <Bell size={10} />
        尚未推送
      </span>
    );
  }

  // "ok" — show subtle time since push
  if (reminder.days_since_last != null && reminder.days_since_last > 0) {
    return (
      <span className="ml-1.5 inline-flex items-center gap-0.5 text-[11px] text-slate-400">
        <Clock size={10} />
        {reminder.days_since_last} 天前
      </span>
    );
  }

  return null;
};

// ── Helper: PushRow ──

const PushRow: React.FC<{
