import { Assessment, AssessmentRecord, TreatmentPlanVersion } from '../types/assessment';
import { AssessmentRecordStorage } from '../utils/assessmentRecordStorage';
import { APP_CONFIG } from '../config/appConfig';

interface DataCenterStorage {
  assessments: Assessment[];
  treatmentPlans: TreatmentPlanVersion[];
  records: AssessmentRecord[];
  lastUpdated: string;
  version: string;
}

interface DataStatistics {
  totalAssessments: number;
  totalRecords: number;
  totalTreatmentPlans: number;
  storageUsed: number;
  storageAvailable: boolean;
  recentAssessments: Assessment[];
}

export class DataCenterService {
  private static STORAGE_KEY = 'rehab_data_center';
  private static VERSION = '1.0';

  static saveAssessment(assessment: Assessment): boolean {
    try {
      const data = this.loadData();
      const existingIndex = data.assessments.findIndex(a => a.id === assessment.id);
      
      if (existingIndex >= 0) {
        data.assessments[existingIndex] = assessment;
      } else {
        data.assessments.push(assessment);
      }
      
      data.lastUpdated = new Date().toISOString();
      return this.saveData(data);
    } catch (error) {
      console.error('保存评估数据失败:', error);
      return false;
    }
  }

  static saveTreatmentPlan(plan: TreatmentPlanVersion): boolean {
    try {
      const data = this.loadData();
      const existingIndex = data.treatmentPlans.findIndex(p => p.id === plan.id);
      
      if (existingIndex >= 0) {
        data.treatmentPlans[existingIndex] = plan;
      } else {
        data.treatmentPlans.push(plan);
      }
      
      data.lastUpdated = new Date().toISOString();
      return this.saveData(data);
    } catch (error) {
      console.error('保存治疗计划失败:', error);
      return false;
    }
  }

  static saveRecord(record: AssessmentRecord): boolean {
    try {
      const data = this.loadData();
      const existingIndex = data.records.findIndex(r => r.id === record.id);
      
      if (existingIndex >= 0) {
        data.records[existingIndex] = record;
      } else {
        data.records.push(record);
      }
      
      data.lastUpdated = new Date().toISOString();
      return this.saveData(data);
    } catch (error) {
      console.error('保存评估记录失败:', error);
      return false;
    }
  }

  static loadAssessments(patientId?: string): Assessment[] {
    const data = this.loadData();
    if (patientId) {
      return data.assessments.filter(a => a.patientId === patientId);
    }
    return data.assessments;
  }

  static loadTreatmentPlans(patientId?: string): TreatmentPlanVersion[] {
    const data = this.loadData();
    if (patientId) {
      return data.treatmentPlans.filter(p => p.patientId === patientId);
    }
    return data.treatmentPlans;
  }

  static loadRecords(patientId?: string): AssessmentRecord[] {
    const data = this.loadData();
    if (patientId) {
      return data.records.filter(r => r.patientId === patientId);
    }
    return data.records;
  }

  static getAssessment(id: string): Assessment | null {
    const data = this.loadData();
    return data.assessments.find(a => a.id === id) || null;
  }

  static getTreatmentPlan(id: string): TreatmentPlanVersion | null {
    const data = this.loadData();
    return data.treatmentPlans.find(p => p.id === id) || null;
  }

  static getRecord(id: string): AssessmentRecord | null {
    const data = this.loadData();
    return data.records.find(r => r.id === id) || null;
  }

  static deleteAssessment(id: string): boolean {
    try {
      const data = this.loadData();
      data.assessments = data.assessments.filter(a => a.id !== id);
      data.lastUpdated = new Date().toISOString();
      return this.saveData(data);
    } catch (error) {
      console.error('删除评估数据失败:', error);
      return false;
    }
  }

  static deleteTreatmentPlan(id: string): boolean {
    try {
      const data = this.loadData();
      data.treatmentPlans = data.treatmentPlans.filter(p => p.id !== id);
      data.lastUpdated = new Date().toISOString();
      return this.saveData(data);
    } catch (error) {
      console.error('删除治疗计划失败:', error);
      return false;
    }
  }

  static deleteRecord(id: string): boolean {
    try {
      const data = this.loadData();
      data.records = data.records.filter(r => r.id !== id);
      data.lastUpdated = new Date().toISOString();
      return this.saveData(data);
    } catch (error) {
      console.error('删除评估记录失败:', error);
      return false;
    }
  }

  static getStatistics(patientId?: string): DataStatistics {
    const data = this.loadData();
    let assessments = data.assessments;
    let records = data.records;
    let treatmentPlans = data.treatmentPlans;

    if (patientId) {
      assessments = assessments.filter(a => a.patientId === patientId);
      records = records.filter(r => r.patientId === patientId);
      treatmentPlans = treatmentPlans.filter(p => p.patientId === patientId);
    }

    const storageUsed = this.getStorageUsed();
    const storageAvailable = storageUsed < APP_CONFIG.STORAGE_LIMITS.CRITICAL_THRESHOLD;

    const recentAssessments = [...assessments]
      .sort((a, b) => b.createdAt - a.createdAt)
      .slice(0, 5);

    return {
      totalAssessments: assessments.length,
      totalRecords: records.length,
      totalTreatmentPlans: treatmentPlans.length,
      storageUsed,
      storageAvailable,
      recentAssessments,
    };
  }

  static exportData(patientId?: string): string {
    const data = this.loadData();
    let exportData = { ...data };

    if (patientId) {
      exportData = {
        ...data,
        assessments: data.assessments.filter(a => a.patientId === patientId),
        records: data.records.filter(r => r.patientId === patientId),
        treatmentPlans: data.treatmentPlans.filter(p => p.patientId === patientId),
      };
    }

    return JSON.stringify({
      ...exportData,
      exportDate: new Date().toISOString(),
    }, null, 2);
  }

  static importData(jsonStr: string): boolean {
    try {
      const importedData = JSON.parse(jsonStr);
      const currentData = this.loadData();

      if (importedData.assessments) {
        currentData.assessments = [
          ...currentData.assessments,
          ...importedData.assessments,
        ];
      }

      if (importedData.records) {
        currentData.records = [
          ...currentData.records,
          ...importedData.records,
        ];
      }

      if (importedData.treatmentPlans) {
        currentData.treatmentPlans = [
          ...currentData.treatmentPlans,
          ...importedData.treatmentPlans,
        ];
      }

      currentData.lastUpdated = new Date().toISOString();
      return this.saveData(currentData);
    } catch (error) {
      console.error('导入数据失败:', error);
      return false;
    }
  }

  static clearData(patientId?: string): boolean {
    try {
      if (patientId) {
        const data = this.loadData();
        data.assessments = data.assessments.filter(a => a.patientId !== patientId);
        data.records = data.records.filter(r => r.patientId !== patientId);
        data.treatmentPlans = data.treatmentPlans.filter(p => p.patientId !== patientId);
        data.lastUpdated = new Date().toISOString();
        return this.saveData(data);
      } else {
        localStorage.removeItem(this.STORAGE_KEY);
        return true;
      }
    } catch (error) {
      console.error('清空数据失败:', error);
      return false;
    }
  }

  private static loadData(): DataCenterStorage {
    try {
      const dataStr = localStorage.getItem(this.STORAGE_KEY);
      if (!dataStr) {
        return this.getDefaultData();
      }

      const data = JSON.parse(dataStr);
      if (data.version !== this.VERSION) {
        console.warn('数据中心版本不匹配，使用默认数据');
        return this.getDefaultData();
      }

      return {
        assessments: data.assessments || [],
        treatmentPlans: data.treatmentPlans || [],
        records: data.records || [],
        lastUpdated: data.lastUpdated || new Date().toISOString(),
        version: data.version || this.VERSION,
      };
    } catch (error) {
      console.error('加载数据中心失败:', error);
      return this.getDefaultData();
    }
  }

  private static saveData(data: DataCenterStorage): boolean {
    try {
      const dataStr = JSON.stringify(data);
      const dataSize = new Blob([dataStr]).size;

      if (dataSize > APP_CONFIG.STORAGE_LIMITS.CRITICAL_THRESHOLD) {
        console.error('数据中心存储容量已达临界值');
        return false;
      }

      localStorage.setItem(this.STORAGE_KEY, dataStr);
      return true;
    } catch (error) {
      console.error('保存数据中心失败:', error);
      return false;
    }
  }

  private static getDefaultData(): DataCenterStorage {
    return {
      assessments: [],
      treatmentPlans: [],
      records: [],
      lastUpdated: new Date().toISOString(),
      version: this.VERSION,
    };
  }

  private static getStorageUsed(): number {
    try {
      const dataStr = localStorage.getItem(this.STORAGE_KEY);
      return dataStr ? new Blob([dataStr]).size : 0;
    } catch (error) {
      return 0;
    }
  }
}

import { Assessment, AssessmentRecord, PostureAssessmentData, RomAssessmentData, MedVoiceAssessmentData } from '../types/assessment';
import { PostureMetrics, PostureIssue } from '../types/posture';

interface StandardizedAssessment {
  id: string;
  patientId: string;
  type: 'posture' | 'rom' | 'medvoice' | 'combined' | 'scale' | 'adams';
  createdAt: number;
  metrics: Record<string, number | string | boolean>;
  issues: Array<{
    type: string;
    severity: 'mild' | 'moderate' | 'severe';
    description: string;
  }>;
  recommendations: string[];
  rawData: any;
}

interface StandardizedRecord {
  id: string;
  patientId: string;
  type: 'front' | 'side' | 'back';
  timestamp: string;
  metrics: Record<string, number>;
  angles: Record<string, number>;
  landmarks: Array<{x: number; y: number}>;
  imageData: string;
  feedback: string;
  improvement: number;
}

export class DataStandardizationService {
  static standardizeAssessment(assessment: Assessment): StandardizedAssessment {
    const standardized: StandardizedAssessment = {
      id: assessment.id,
      patientId: assessment.patientId,
      type: assessment.type,
      createdAt: assessment.createdAt,
      metrics: {},
      issues: [],
      recommendations: [],
      rawData: assessment.data,
    };

    if (assessment.data.posture) {
      this.standardizePostureData(assessment.data.posture, standardized);
    }

    if (assessment.data.rom) {
      this.standardizeRomData(assessment.data.rom, standardized);
    }

    if (assessment.data.medvoice) {
      this.standardizeMedVoiceData(assessment.data.medvoice, standardized);
    }

    return standardized;
  }

  static standardizeRecord(record: AssessmentRecord): StandardizedRecord {
    return {
      id: record.id,
      patientId: record.patientId,
      type: record.assessmentType,
      timestamp: record.timestamp,
      metrics: record.metrics as Record<string, number>,
      angles: record.angles,
      landmarks: Array.isArray(record.landmarks) && record.landmarks.length > 0 && typeof record.landmarks[0] === 'object'
        ? record.landmarks as Array<{x: number; y: number}>
        : this.convertLandmarksArray(record.landmarks),
      imageData: record.imageData,
      feedback: record.feedback || '',
      improvement: record.improvement || 0,
    };
  }

  static calculateMetrics(assessments: Assessment[]): Record<string, number> {
    const metrics: Record<string, number> = {};
    const postureAssessments = assessments.filter(a => a.data.posture);
    const romAssessments = assessments.filter(a => a.data.rom);

    if (postureAssessments.length > 0) {
      const postureMetrics = this.calculatePostureMetrics(postureAssessments);
      Object.assign(metrics, postureMetrics);
    }

    if (romAssessments.length > 0) {
      const romMetrics = this.calculateRomMetrics(romAssessments);
      Object.assign(metrics, romMetrics);
    }

    metrics.assessmentCount = assessments.length;
    metrics.averageConfidence = assessments.reduce((sum, a) => {
      return sum + (a.data.posture?.confidence || 0);
    }, 0) / assessments.length;

    return metrics;
  }

  static generateInsights(assessments: Assessment[]): string[] {
    const insights: string[] = [];
    const metrics = this.calculateMetrics(assessments);

    if (metrics.assessmentCount > 1) {
      insights.push(`共进行了 ${metrics.assessmentCount} 次评估，平均置信度为 ${metrics.averageConfidence?.toFixed(2) || 0}`);
    }

    if (metrics.postureScore) {
      if (metrics.postureScore > 80) {
        insights.push('姿势评估结果良好，整体姿态保持稳定');
      } else if (metrics.postureScore > 60) {
        insights.push('姿势评估结果一般，存在轻度姿态问题');
      } else {
        insights.push('姿势评估结果较差，存在明显姿态问题');
      }
    }

    if (metrics.romScore) {
      if (metrics.romScore > 80) {
        insights.push('关节活动度评估结果良好，关节活动范围正常');
      } else if (metrics.romScore > 60) {
        insights.push('关节活动度评估结果一般，存在轻度活动受限');
      } else {
        insights.push('关节活动度评估结果较差，存在明显活动受限');
      }
    }

    return insights;
  }

  private static standardizePostureData(data: PostureAssessmentData, standardized: StandardizedAssessment) {
    if (data.metrics) {
      Object.entries(data.metrics).forEach(([key, value]) => {
        if (typeof value === 'number') {
          standardized.metrics[`posture_${key}`] = value;
        }
      });
    }

    if (data.issues) {
      data.issues.forEach(issue => {
        standardized.issues.push({
          type: issue.type,
          severity: this.mapSeverity(issue.severity),
          description: issue.description,
        });
      });
    }

    if (data.confidence) {
      standardized.metrics.posture_confidence = data.confidence;
    }
  }

  private static standardizeRomData(data: RomAssessmentData, standardized: StandardizedAssessment) {
    data.items.forEach((item, index) => {
      standardized.metrics[`rom_${item.joint}_${item.direction}`] = item.angle;
    });

    if (data.recommendations) {
      standardized.recommendations.push(...data.recommendations);
    }
  }

  private static standardizeMedVoiceData(data: MedVoiceAssessmentData, standardized: StandardizedAssessment) {
    standardized.metrics.medvoice_session_length = data.transcript.length;
    standardized.rawData.medvoice = data;
  }

  private static convertLandmarksArray(landmarks: any): Array<{x: number; y: number}> {
    if (Array.isArray(landmarks) && landmarks.length % 2 === 0) {
      const result: Array<{x: number; y: number}> = [];
      for (let i = 0; i < landmarks.length; i += 2) {
        result.push({ x: landmarks[i], y: landmarks[i + 1] });
      }
      return result;
    }
    return [];
  }

  private static mapSeverity(severity: string): 'mild' | 'moderate' | 'severe' {
    const severityMap: Record<string, 'mild' | 'moderate' | 'severe'> = {
      mild: 'mild',
      moderate: 'moderate',
      severe: 'severe',
      low: 'mild',
      medium: 'moderate',
      high: 'severe',
    };
    return severityMap[severity.toLowerCase()] || 'moderate';
  }

  private static calculatePostureMetrics(assessments: Assessment[]): Record<string, number> {
    const metrics: Record<string, number> = {};
    const postureData = assessments.map(a => a.data.posture).filter(Boolean) as PostureAssessmentData[];

    if (postureData.length > 0) {
      const confidenceSum = postureData.reduce((sum, data) => sum + (data.confidence || 0), 0);
      metrics.postureConfidence = confidenceSum / postureData.length;

      const issueCounts = postureData.reduce((count, data) => {
        return count + (data.issues?.length || 0);
      }, 0);
      metrics.postureIssueCount = issueCounts / postureData.length;

      metrics.postureScore = this.calculatePostureScore(postureData);
    }

    return metrics;
  }

  private static calculateRomMetrics(assessments: Assessment[]): Record<string, number> {
    const metrics: Record<string, number> = {};
    const romData = assessments.map(a => a.data.rom).filter(Boolean) as RomAssessmentData[];

    if (romData.length > 0) {
      let totalValue = 0;
      let count = 0;

      romData.forEach(data => {
        data.items.forEach(item => {
          totalValue += item.angle;
          count++;
        });
      });

      metrics.romAverage = count > 0 ? totalValue / count : 0;
      metrics.romScore = this.calculateRomScore(romData);
    }

    return metrics;
  }

  private static calculatePostureScore(postureData: PostureAssessmentData[]): number {
    let totalScore = 0;
    postureData.forEach(data => {
      if (data.metrics) {
        const score = this.calculateSinglePostureScore(data.metrics);
        totalScore += score;
      }
    });
    return postureData.length > 0 ? totalScore / postureData.length : 0;
  }

  private static calculateSinglePostureScore(metrics: PostureMetrics): number {
    let score = 100;
    
    if (metrics.headDeviation) score -= Math.abs(metrics.headDeviation) * 2;
    if (metrics.shoulderAngle) score -= Math.abs(metrics.shoulderAngle) * 1.5;
    if (metrics.hipAngle) score -= Math.abs(metrics.hipAngle) * 1.5;
    
    return Math.max(0, Math.min(100, score));
  }

  private static calculateRomScore(romData: RomAssessmentData[]): number {
    let totalScore = 0;
    romData.forEach(data => {
      data.items.forEach(item => {
        const score = this.calculateSingleRomScore(item.angle, item.joint, item.direction);
        totalScore += score;
      });
    });
    const totalItems = romData.reduce((sum, data) => sum + data.items.length, 0);
    return totalItems > 0 ? totalScore / totalItems : 0;
  }

  private static calculateSingleRomScore(value: number, joint: string, movement: string): number {
    const normalRanges: Record<string, Record<string, [number, number]>> = {
      shoulder: {
        flexion: [0, 180],
        extension: [0, 60],
        abduction: [0, 180],
        adduction: [0, 45],
        internal_rotation: [0, 90],
        external_rotation: [0, 90],
      },
      elbow: {
        flexion: [0, 145],
        extension: [0, 0],
      },
      wrist: {
        flexion: [0, 90],
        extension: [0, 70],
      },
      hip: {
        flexion: [0, 120],
        extension: [0, 30],
        abduction: [0, 45],
        adduction: [0, 30],
        internal_rotation: [0, 45],
        external_rotation: [0, 45],
      },
      knee: {
        flexion: [0, 140],
        extension: [0, 0],
      },
      ankle: {
        dorsiflexion: [0, 20],
        plantarflexion: [0, 45],
      },
    };

    const range = normalRanges[joint]?.[movement];
    if (!range) return 50;

    const [min, max] = range;
    const normalRange = max - min;
    const deviation = Math.abs(value - max);
    const score = 100 - (deviation / normalRange) * 100;
    
    return Math.max(0, Math.min(100, score));
  }
}

import { CONFIG } from '../config';

export class LLMReportService {
  private apiEndpoint: string;

  constructor() {
    this.apiEndpoint = `${CONFIG.api.baseUrl}/api/llm/report`;
  }

  async generateReport(prompt: string, format: 'markdown' | 'html' | 'pdf'): Promise<string> {
    try {
      const response = await this.callLLM(prompt);
      let content = this.extractContent(response);

      if (format === 'html') {
        content = this.convertToHtml(content);
      } else if (format === 'pdf') {
        content = this.convertToPdf(content);
      }

      return content;
    } catch (error) {
      console.error('LLM报告生成失败:', error);
      return this.generateFallbackReport(prompt, format);
    }
  }

  private async callLLM(prompt: string): Promise<any> {
    const response = await fetch(this.apiEndpoint, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({ prompt })
    });

    if (!response.ok) {
      throw new Error(`LLM API请求失败: ${response.status}`);
    }

    return await response.json();
  }

  private extractContent(response: any): string {
    if (typeof response?.content === 'string' && response.content.trim()) {
      return response.content;
    }
    if (response && response.choices && response.choices.length > 0) {
      return response.choices[0].message?.content || '';
    }
    throw new Error('LLM响应格式错误');
  }

  private convertToHtml(markdown: string): string {
    // 简单的Markdown转HTML
    let html = markdown
      .replace(/^# (.*$)/gim, '<h1>$1</h1>')
      .replace(/^## (.*$)/gim, '<h2>$1</h2>')
      .replace(/^### (.*$)/gim, '<h3>$1</h3>')
      .replace(/\*\*(.*?)\*\*/gim, '<strong>$1</strong>')
      .replace(/\*(.*?)\*/gim, '<em>$1</em>')
      .replace(/\[(.*?)\]\((.*?)\)/gim, '<a href="$2">$1</a>')
      .replace(/^\- (.*$)/gim, '<li>$1</li>')
      .replace(/(<li>.*<\/li>)/s, '<ul>$1</ul>')
      .replace(/\n/gim, '<br>');

    return `
    <!DOCTYPE html>
    <html>
    <head>
      <meta charset="UTF-8">
      <title>康复报告</title>
      <style>
        body { font-family: Arial, sans-serif; line-height: 1.6; padding: 20px; }
        h1, h2, h3 { color: #333; }
        ul { margin-left: 20px; }
        strong { font-weight: bold; }
        em { font-style: italic; }
      </style>
    </head>
    <body>
      ${html}
    </body>
    </html>
    `;
  }

  private convertToPdf(content: string): string {
    // 这里只是返回内容，实际PDF生成需要使用专门的库
    return content;
  }

  private generateFallbackReport(prompt: string, format: 'markdown' | 'html' | 'pdf'): string {
    const fallbackContent = `
# 报告生成失败

## 原因
- LLM API调用失败
- 可能是网络问题或API密钥配置错误

## 建议
1. 检查网络连接
2. 确认API密钥是否正确配置
3. 稍后重试

## 原始请求
${prompt.substring(0, 500)}...
`;

    if (format === 'html') {
      return this.convertToHtml(fallbackContent);
    }

    return fallbackContent;
  }

  async generateSummary(data: any): Promise<string> {
    try {
      const prompt = `
      请根据以下康复数据生成一份简要总结：

      ${JSON.stringify(data, null, 2)}

      总结要求：
      1. 控制在200字以内
      2. 突出重点发现和关键指标
      3. 使用专业但简洁的语言
      4. 包含主要问题和建议
      `;

      const response = await this.callLLM(prompt);
      return this.extractContent(response);
    } catch (error) {
      console.error('生成总结失败:', error);
      return '无法生成总结，请检查网络连接或API配置。';
    }
  }

  async generateRecommendations(data: any): Promise<string[]> {
    try {
      const prompt = `
      请根据以下康复数据生成具体的康复建议：

      ${JSON.stringify(data, null, 2)}

      建议要求：
      1. 每条建议独立成项
      2. 具体可行
      3. 针对发现的问题
      4. 按优先级排序
      `;

      const response = await this.callLLM(prompt);
      const content = this.extractContent(response);
      return content.split('\n').filter(line => line.trim() && line.startsWith('-')).map(line => line.trim());
    } catch (error) {
      console.error('生成建议失败:', error);
      return ['保持定期康复训练', '注意姿势纠正', '遵循医生建议'];
    }
  }

  async analyzeProgress(previousData: any, currentData: any): Promise<string> {
    try {
      const prompt = `
      请分析以下康复进度数据：

      之前的评估：
      ${JSON.stringify(previousData, null, 2)}

      当前的评估：
      ${JSON.stringify(currentData, null, 2)}

      分析要求：
      1. 对比两个评估的差异
      2. 评估康复进展情况
      3. 指出改善的方面和仍需注意的问题
      4. 提供下一步建议
      5. 使用专业但易于理解的语言
      `;

      const response = await this.callLLM(prompt);
      return this.extractContent(response);
    } catch (error) {
      console.error('分析进度失败:', error);
      return '无法分析进度，请检查数据或API配置。';
    }
  }
}

import { Assessment, AssessmentRecord, TreatmentPlanVersion } from '../types/assessment';
import { DataCenterService } from './DataCenterService';
import { DataStandardizationService } from './DataStandardizationService';
import { LLMReportService } from './LLMReportService';

export type ReportType = 'assessment' | 'treatment' | 'progress' | 'comprehensive';
export type ReportFormat = 'markdown' | 'html' | 'pdf';

interface ReportConfig {
  type: ReportType;
  format: ReportFormat;
  patientId: string;
  assessmentIds?: string[];
  treatmentPlanId?: string;
  timeRange?: {
    start: number;
    end: number;
  };
  includeCharts?: boolean;
  includeRecommendations?: boolean;
  includeRawData?: boolean;
}

interface ReportData {
  id: string;
  patientId: string;
  type: ReportType;
  format: ReportFormat;
  title: string;
  content: string;
  createdAt: number;
  data: {
    assessments: Assessment[];
    treatmentPlans: TreatmentPlanVersion[];
    records: AssessmentRecord[];
    metrics: Record<string, number>;
    insights: string[];
  };
}

export class ReportGenerator {
  static async generateReport(config: ReportConfig): Promise<ReportData> {
    try {
      const data = await this.collectData(config);
      const standardizedData = this.processData(data);
      const reportContent = await this.generateContent(standardizedData, config);
      
      return {
        id: `report_${Date.now()}`,
        patientId: config.patientId,
        type: config.type,
        format: config.format,
        title: this.generateTitle(config, data),
        content: reportContent,
        createdAt: Date.now(),
        data: standardizedData,
      };
    } catch (error) {
      console.error('生成报告失败:', error);
      throw error;
    }
  }

  private static async collectData(config: ReportConfig): Promise<{
    assessments: Assessment[];
    treatmentPlans: TreatmentPlanVersion[];
    records: AssessmentRecord[];
  }> {
    let assessments: Assessment[] = [];
    let treatmentPlans: TreatmentPlanVersion[] = [];
    let records: AssessmentRecord[] = [];

    if (config.assessmentIds) {
      assessments = config.assessmentIds.map(id => {
        const assessment = DataCenterService.getAssessment(id);
        if (!assessment) {
          throw new Error(`评估ID ${id} 不存在`);
        }
        return assessment;
      });
    } else {
      assessments = DataCenterService.loadAssessments(config.patientId);
      
      if (config.timeRange) {
        assessments = assessments.filter(a => 
          a.createdAt >= config.timeRange.start && 
          a.createdAt <= config.timeRange.end
        );
      }
    }

    treatmentPlans = DataCenterService.loadTreatmentPlans(config.patientId);
    if (config.treatmentPlanId) {
      treatmentPlans = treatmentPlans.filter(p => p.id === config.treatmentPlanId);
    }

    records = DataCenterService.loadRecords(config.patientId);
    if (config.timeRange) {
      records = records.filter(r => {
        const timestamp = new Date(r.timestamp).getTime();
        return timestamp >= config.timeRange.start && timestamp <= config.timeRange.end;
      });
    }

    return { assessments, treatmentPlans, records };
  }

  private static processData(data: {
    assessments: Assessment[];
    treatmentPlans: TreatmentPlanVersion[];
    records: AssessmentRecord[];
  }): {
    assessments: Assessment[];
    treatmentPlans: TreatmentPlanVersion[];
    records: AssessmentRecord[];
    metrics: Record<string, number>;
    insights: string[];
  } {
    const metrics = DataStandardizationService.calculateMetrics(data.assessments);
    const insights = DataStandardizationService.generateInsights(data.assessments);

    return {
      ...data,
      metrics,
      insights,
    };
  }

  private static async generateContent(
    data: {
      assessments: Assessment[];
      treatmentPlans: TreatmentPlanVersion[];
      records: AssessmentRecord[];
      metrics: Record<string, number>;
      insights: string[];
    },
    config: ReportConfig
  ): Promise<string> {
    switch (config.type) {
      case 'assessment':
        return await this.generateAssessmentReport(data, config);
      case 'treatment':
        return await this.generateTreatmentReport(data, config);
      case 'progress':
        return await this.generateProgressReport(data, config);
      case 'comprehensive':
        return await this.generateComprehensiveReport(data, config);
      default:
        throw new Error(`不支持的报告类型: ${config.type}`);
    }
  }

  private static async generateAssessmentReport(
    data: any,
    config: ReportConfig
  ): Promise<string> {
    const llmService = new LLMReportService();
    const standardizedAssessments = data.assessments.map(a => 
      DataStandardizationService.standardizeAssessment(a)
    );

    const prompt = `
    作为康复评估专家，请根据以下评估数据生成一份专业的评估报告：

    评估数据：
    ${JSON.stringify(standardizedAssessments, null, 2)}

    评估指标：
    ${JSON.stringify(data.metrics, null, 2)}

    生成要求：
    1. 报告应包括：评估概述、详细发现、问题分析、建议
    2. 使用专业但易于理解的语言
    3. 重点突出异常指标和需要关注的问题
    4. 提供具体的康复建议
    5. 报告格式为${config.format === 'markdown' ? 'Markdown' : 'HTML'}
    `;

    return await llmService.generateReport(prompt, config.format);
  }

  private static async generateTreatmentReport(
    data: any,
    config: ReportConfig
  ): Promise<string> {
    const llmService = new LLMReportService();

    const prompt = `
    作为康复治疗专家，请根据以下治疗计划数据生成一份专业的治疗报告：

    治疗计划：
    ${JSON.stringify(data.treatmentPlans, null, 2)}

    相关评估：
    ${JSON.stringify(data.assessments, null, 2)}

    生成要求：
    1. 报告应包括：治疗计划概述、治疗目标、具体方案、预期效果
    2. 使用专业但易于理解的语言
    3. 详细说明每个治疗步骤的目的和方法
    4. 提供治疗进度跟踪建议
    5. 报告格式为${config.format === 'markdown' ? 'Markdown' : 'HTML'}
    `;

    return await llmService.generateReport(prompt, config.format);
  }

  private static async generateProgressReport(
    data: any,
    config: ReportConfig
  ): Promise<string> {
    const llmService = new LLMReportService();

    const prompt = `
    作为康复评估专家，请根据以下评估数据生成一份进度报告：

    评估数据：
    ${JSON.stringify(data.assessments, null, 2)}

    评估记录：
    ${JSON.stringify(data.records, null, 2)}

    评估指标：
    ${JSON.stringify(data.metrics, null, 2)}

    生成要求：
    1. 报告应包括：进度概述、改善情况、存在问题、后续建议
    2. 使用专业但易于理解的语言
    3. 分析评估数据的变化趋势
    4. 评估当前康复效果
    5. 报告格式为${config.format === 'markdown' ? 'Markdown' : 'HTML'}
    `;

    return await llmService.generateReport(prompt, config.format);
  }

  private static async generateComprehensiveReport(
    data: any,
    config: ReportConfig
  ): Promise<string> {
    const llmService = new LLMReportService();

    const prompt = `
    作为康复医学专家，请根据以下综合数据生成一份全面的康复报告：

    评估数据：
    ${JSON.stringify(data.assessments, null, 2)}

    治疗计划：
    ${JSON.stringify(data.treatmentPlans, null, 2)}

    评估记录：
    ${JSON.stringify(data.records, null, 2)}

    评估指标：
    ${JSON.stringify(data.metrics, null, 2)}

    生成要求：
    1. 报告应包括：患者概况、评估结果、治疗方案、康复进度、未来建议
    2. 使用专业但易于理解的语言
    3. 综合分析所有数据，提供整体康复状况评估
    4. 针对不同方面提供具体建议
    5. 报告格式为${config.format === 'markdown' ? 'Markdown' : 'HTML'}
    `;

    return await llmService.generateReport(prompt, config.format);
  }

  private static generateTitle(config: ReportConfig, data: any): string {
    const date = new Date().toISOString().split('T')[0];
    
    switch (config.type) {
      case 'assessment':
        return `评估报告 - ${date}`;
      case 'treatment':
        return `治疗计划报告 - ${date}`;
      case 'progress':
        return `康复进度报告 - ${date}`;
      case 'comprehensive':
        return `综合康复报告 - ${date}`;
      default:
        return `康复报告 - ${date}`;
    }
  }

  static saveReport(report: ReportData): boolean {
    try {
      const reports = this.loadReports();
      reports.push(report);
      localStorage.setItem('rehab_reports', JSON.stringify(reports));
      return true;
    } catch (error) {
      console.error('保存报告失败:', error);
      return false;
    }
  }

  static loadReports(patientId?: string): ReportData[] {
    try {
      const reportsStr = localStorage.getItem('rehab_reports');
      if (!reportsStr) return [];

      const reports = JSON.parse(reportsStr) as ReportData[];
      if (patientId) {
        return reports.filter(r => r.patientId === patientId);
      }
      return reports;
    } catch (error) {
      console.error('加载报告失败:', error);
      return [];
    }
  }

  static getReport(id: string): ReportData | null {
    const reports = this.loadReports();
    return reports.find(r => r.id === id) || null;
  }

  static deleteReport(id: string): boolean {
    try {
      const reports = this.loadReports();
      const filtered = reports.filter(r => r.id !== id);
      localStorage.setItem('rehab_reports', JSON.stringify(filtered));
      return true;
    } catch (error) {
      console.error('删除报告失败:', error);
      return false;
    }
  }
}

import type { ScaleAssessmentData } from '@/types/assessment';
import type {
