import { describe, it, expect, beforeEach } from 'vitest';
import { useTreatmentPlanStore } from '../useTreatmentPlanStore';
import type { TreatmentPlanVersion } from '../../types/assessment';

describe('useTreatmentPlanStore - 版本管理', () => {
  beforeEach(() => {
    // 重置状态
    const { clearContent } = useTreatmentPlanStore.getState();
    clearContent();
    // 清空版本列表
    useTreatmentPlanStore.setState({
      versions: [],
      currentVersionId: null,
      comparingVersions: [null, null]
    });
  });

  describe('初始状态', () => {
    it('应该有正确的初始状态', () => {
      const state = useTreatmentPlanStore.getState();
      
      expect(state.versions).toEqual([]);
      expect(state.currentVersionId).toBeNull();
      expect(state.comparingVersions).toEqual([null, null]);
    });
  });

  describe('saveVersion', () => {
    it('应该保存新版本', () => {
      const { saveVersion } = useTreatmentPlanStore.getState();
      
      saveVersion('治疗计划内容', 'assessment_001', 'patient_001');
      
      const state = useTreatmentPlanStore.getState();
      expect(state.versions).toHaveLength(1);
      expect(state.versions[0].content).toBe('治疗计划内容');
      expect(state.versions[0].isCurrent).toBe(true);
    });

    it('应该自动递增版本号', () => {
      const { saveVersion } = useTreatmentPlanStore.getState();
      
      saveVersion('版本1', 'assessment_001', 'patient_001');
      saveVersion('版本2', 'assessment_001', 'patient_001');
      
      const state = useTreatmentPlanStore.getState();
      expect(state.versions).toHaveLength(2);
      expect(state.versions[0].version).toBe(1);
      expect(state.versions[1].version).toBe(2);
    });

    it('应该将旧版本标记为非当前', () => {
      const { saveVersion } = useTreatmentPlanStore.getState();
      
      saveVersion('版本1', 'assessment_001', 'patient_001');
      saveVersion('版本2', 'assessment_001', 'patient_001');
      
      const state = useTreatmentPlanStore.getState();
      expect(state.versions[0].isCurrent).toBe(false);
      expect(state.versions[1].isCurrent).toBe(true);
    });
  });

  describe('switchVersion', () => {
    it('应该切换到指定版本', () => {
      const { saveVersion, switchVersion } = useTreatmentPlanStore.getState();
      
      saveVersion('版本1', 'assessment_001', 'patient_001');
      const versionId = useTreatmentPlanStore.getState().versions[0].id;
      
      switchVersion(versionId);
      
      const state = useTreatmentPlanStore.getState();
      expect(state.currentVersionId).toBe(versionId);
      expect(state.currentContent).toBe('版本1');
    });

    it('应该更新当前版本标记', () => {
      const { saveVersion, switchVersion } = useTreatmentPlanStore.getState();
      
      saveVersion('版本1', 'assessment_001', 'patient_001');
      saveVersion('版本2', 'assessment_001', 'patient_001');
      
      // 切换到第一个版本（versions[0]）
      const firstVersionId = useTreatmentPlanStore.getState().versions[0].id;
      switchVersion(firstVersionId);
      
      const state = useTreatmentPlanStore.getState();
      // 切换后，versions[0] 应该是当前版本
      expect(state.versions[0].isCurrent).toBe(true);
      expect(state.versions[1].isCurrent).toBe(false);
    });
  });

  describe('deleteVersion', () => {
    it('应该删除指定版本', () => {
      const { saveVersion, deleteVersion } = useTreatmentPlanStore.getState();
      
      saveVersion('版本1', 'assessment_001', 'patient_001');
      saveVersion('版本2', 'assessment_001', 'patient_001');
      
      const versionId = useTreatmentPlanStore.getState().versions[0].id;
      deleteVersion(versionId);
      
      const state = useTreatmentPlanStore.getState();
      expect(state.versions).toHaveLength(1);
      expect(state.versions[0].content).toBe('版本2');
    });

    it('删除当前版本时应切换到最新版本', () => {
      const { saveVersion, deleteVersion } = useTreatmentPlanStore.getState();
      
      saveVersion('版本1', 'assessment_001', 'patient_001');
      saveVersion('版本2', 'assessment_001', 'patient_001');
      
      const currentVersionId = useTreatmentPlanStore.getState().currentVersionId;
      deleteVersion(currentVersionId!);
      
      const state = useTreatmentPlanStore.getState();
      expect(state.currentContent).toBe('版本1');
      expect(state.versions[0].isCurrent).toBe(true);
    });

    it('删除所有版本时应清空当前内容', () => {
      const { saveVersion, deleteVersion } = useTreatmentPlanStore.getState();
      
      saveVersion('版本1', 'assessment_001', 'patient_001');
      
      const versionId = useTreatmentPlanStore.getState().versions[0].id;
      deleteVersion(versionId);
      
      const state = useTreatmentPlanStore.getState();
      expect(state.versions).toHaveLength(0);
      expect(state.currentVersionId).toBeNull();
      expect(state.currentContent).toBe('');
    });
  });

  describe('updateVersionTags', () => {
    it('应该更新版本标签', () => {
      const { saveVersion, updateVersionTags } = useTreatmentPlanStore.getState();
      
      saveVersion('版本1', 'assessment_001', 'patient_001');
      const versionId = useTreatmentPlanStore.getState().versions[0].id;
      
      updateVersionTags(versionId, ['康复', '肩部']);
      
      const state = useTreatmentPlanStore.getState();
      expect(state.versions[0].tags).toEqual(['康复', '肩部']);
    });
  });

  describe('updateVersionNotes', () => {
    it('应该更新版本备注', () => {
      const { saveVersion, updateVersionNotes } = useTreatmentPlanStore.getState();
      
      saveVersion('版本1', 'assessment_001', 'patient_001');
      const versionId = useTreatmentPlanStore.getState().versions[0].id;
      
      updateVersionNotes(versionId, '第一次生成');
      
      const state = useTreatmentPlanStore.getState();
      expect(state.versions[0].notes).toBe('第一次生成');
    });
  });

  describe('startCompare', () => {
    it('应该开始版本对比', () => {
      const { startCompare } = useTreatmentPlanStore.getState();
      
      startCompare('version_1', 'version_2');
      
      const state = useTreatmentPlanStore.getState();
      expect(state.comparingVersions).toEqual(['version_1', 'version_2']);
    });
  });

  describe('endCompare', () => {
    it('应该结束版本对比', () => {
      const { startCompare, endCompare } = useTreatmentPlanStore.getState();
      
      startCompare('version_1', 'version_2');
      endCompare();
      
      const state = useTreatmentPlanStore.getState();
      expect(state.comparingVersions).toEqual([null, null]);
    });
  });
});

import { create } from 'zustand';
import { db } from '@/lib/db';
import type { Patient } from '@/types/patient';
import { generateSessionId } from '@/lib/session-utils';
import { formatPatientSearch } from '@/lib/patient-utils';
import { IntegrationService, type SyncScreeningPayload } from '@/services/integrationService';
import type { Assessment, PostureAssessmentData, ScaleAssessmentData } from '@/types/assessment';

const SHORT_CODE_ALPHABET = 'ABCDEFGHJKLMNPRTUVWXYZ';  // 20字符，无 I/O/Q

const generateCanonicalPatientId = () => `pat_${crypto.randomUUID().replace(/-/g, '').slice(0, 12)}`;
const generateShortCode = () => {
  let code = '';
  for (let i = 0; i < 4; i++) {
    code += SHORT_CODE_ALPHABET[Math.floor(Math.random() * SHORT_CODE_ALPHABET.length)];
  }
  return code;
};
export { generateCanonicalPatientId, generateShortCode };

interface PatientState {
  patients: Patient[];
  currentPatient: Patient | null;
  isLoading: boolean;
  error: string | null;

  setCurrentPatient: (patient: Patient | null) => void;
  addPatient: (name?: string, predefinedId?: string, predefinedShortCode?: string) => Promise<Patient>;
  updatePatient: (id: string, updates: Partial<Patient>) => Promise<void>;
  deletePatient: (id: string) => Promise<void>;
  loadPatients: () => Promise<void>;
  searchPatients: (query: string) => Patient[];
  getPatientById: (id: string) => Patient | undefined;
  importSquatLabScreening: (payload: SyncScreeningPayload, patientId?: string) => Promise<Patient>;
  importScaleAssessment: (patientId: string, scaleData: ScaleAssessmentData, sessionId?: string) => Promise<void>;
}

export const usePatientStore = create<PatientState>((set, get) => ({
  patients: [],
  currentPatient: null,
  isLoading: false,
  error: null,

  setCurrentPatient: (patient) => set({ currentPatient: patient }),

  addPatient: async (name?: string, predefinedId?: string, predefinedShortCode?: string): Promise<Patient> => {
    set({ isLoading: true, error: null });

    // 统一使用 pat_xxx 格式，与早筛导入一致
    const patientId = predefinedId || generateCanonicalPatientId();
    // 预生成临床短码（后端创建时确认唯一性）
    const shortCode = predefinedShortCode || generateShortCode();

    const exists = await db.patients.get(patientId);
    if (exists) {
      throw new Error('患者编号冲突，请重试');
    }

    const patient: Patient = {
      id: patientId,
      shortCode,
      name,
      createdAt: Date.now(),
      updatedAt: Date.now(),
    };

    await db.patients.add(patient);

    // 同步到 Python 后端，确保患者存在于统一数据源中
    try {
      const result = await IntegrationService.ensurePatient({
        patient_id: patientId,
        display_name: name,
        patient_code: shortCode,
        short_code: shortCode,
      });
      // 以后端返回的 short_code 为准（可能在碰撞时重新生成）
      const confirmedCode = result.patient_code || result.short_code;
      if (confirmedCode && confirmedCode !== shortCode) {
        patient.shortCode = confirmedCode;
        await db.patients.put(patient);
      }
    } catch (err) {
      console.warn('[PatientStore] Failed to sync patient to backend (non-blocking):', err);
    }

    set((state) => ({
      patients: [patient, ...state.patients],
      currentPatient: patient,
      isLoading: false,
    }));

    return patient;
  },

  updatePatient: async (id: string, updates: Partial<Patient>): Promise<void> => {
    set({ isLoading: true, error: null });

    const existing = await db.patients.get(id);
    if (!existing) {
      throw new Error('患者不存在');
    }

    const updated = {
      ...existing,
      ...updates,
      updatedAt: Date.now(),
    };

    await db.patients.put(updated);

    set((state) => ({
      patients: state.patients.map((p) => (p.id === id ? updated : p)),
      currentPatient: state.currentPatient?.id === id ? updated : state.currentPatient,
      isLoading: false,
    }));
  },

  deletePatient: async (id: string): Promise<void> => {
    set({ isLoading: true, error: null });

    await db.patients.delete(id);
    await db.sessions.where('patientId').equals(id).delete();

    set((state) => ({
      patients: state.patients.filter((p) => p.id !== id),
      currentPatient: state.currentPatient?.id === id ? null : state.currentPatient,
      isLoading: false,
    }));
  },

  loadPatients: async () => {
    set({ isLoading: true, error: null });

    const patients = await db.patients.orderBy('createdAt').reverse().toArray();

    set({ patients, isLoading: false });
  },

  searchPatients: (query: string): Patient[] => {
    const { patients } = get();
    if (!query.trim()) return patients;

    return patients.filter((p) => formatPatientSearch(p, query));
  },

  getPatientById: (id) => {
    const { patients } = get();
    return patients.find((p) => p.id === id);
  },

  importSquatLabScreening: async (payload: SyncScreeningPayload, patientId?: string): Promise<Patient> => {
    set({ isLoading: true, error: null });
    try {
      const screeningTime = new Date(payload.created_at).getTime();
      let patient: Patient;

      const targetId = patientId || null;
      let existing = targetId ? await db.patients.get(targetId) : null;

      if (existing) {
        // Associate with existing patient
        const tags = Array.from(new Set([...(existing.tags || []), '来自早筛', '已关联早筛']));
        let updatedNotes = existing.notes || '';
        if (payload.integrated_report) {
          updatedNotes += `\n\n[已关联早筛记录 - ${new Date(payload.created_at).toLocaleDateString()}]\n综合风险: ${payload.integrated_report.overall_risk === 'low' ? '低风险' : '预警关注'}\n结论摘要: ${payload.integrated_report.summary}`;
        }

        patient = {
          ...existing,
          shortCode: existing.shortCode || generateShortCode(),
          tags,
          notes: updatedNotes,
          updatedAt: screeningTime
        };
        await db.patients.put(patient);
      } else {
        // Create new patient
      const newPatientId = targetId || generateCanonicalPatientId();
      const shortCode = generateShortCode();
        const tags = ['来自早筛', payload.integrated_report?.overall_risk === 'low' ? '体态优秀' : '脊柱侧弯预警'];
        const notes = `年龄: ${payload.subject.age ?? '未知'}岁 | 身高: ${payload.subject.height_cm ?? '未知'}cm | 性别: ${payload.subject.sex === 'male' ? '男' : payload.subject.sex === 'female' ? '女' : '未知'}\n早筛备注: ${payload.subject.notes || '无'}\n\n[早筛结论摘要]\n${payload.integrated_report?.summary || '暂无摘要'}`;

        patient = {
          id: newPatientId,
          shortCode,
          name: payload.subject.display_name,
          createdAt: screeningTime,
          updatedAt: screeningTime,
          tags,
          notes
        };
        await db.patients.add(patient);
      }

      // Start clinical session mapping
      const sequence = await db.sessions.where('patientId').equals(patient.id).toArray().then(sessions => {
        if (sessions.length === 0) return 1;
        return Math.max(...sessions.map(s => s.sequence)) + 1;
      });

      const sessionId = generateSessionId(patient.shortCode || patient.id, sequence);

      // Extract metrics from early screening protocols
      const extractedMetrics: any = {};
      payload.protocol_results.forEach(r => {
        if (r.status === 'completed' && r.metrics) {
          if (r.protocol === 'static_posture') {
            Object.entries(r.metrics).forEach(([k, v]) => {
              if (typeof v === 'number') {
                extractedMetrics[k] = v;
              }
            });
          } else if (r.protocol === 'squat_screening') {
            if (r.metrics.left_knee_valgus_deg != null) {
              extractedMetrics.leftKneeValgus = r.metrics.left_knee_valgus_deg;
            }
            if (r.metrics.right_knee_valgus_deg != null) {
              extractedMetrics.rightKneeValgus = r.metrics.right_knee_valgus_deg;
            }
            if (r.metrics.psi_score != null) {
              extractedMetrics.stabilityScore = r.metrics.psi_score * 100;
            } else if (r.psi_score != null) {
              extractedMetrics.stabilityScore = r.psi_score * 100;
            }
          } else if (r.protocol === 'adams_forward_bend') {
            if (r.metrics.atr_angle_deg != null) {
              extractedMetrics.atrAngle = r.metrics.atr_angle_deg;
            }
          }
        }
      });

      // Map early screening protocol results into clinical posture assessment
      const postureData: PostureAssessmentData = {
        mode: 'stepped',
        view: 'front',
        confidence: 0.95,
        metrics: extractedMetrics,
        auxiliaryDiagnosis: `
### 早筛会话详情
- **筛查会话**: ${payload.session_id}
- **受试者 ID**: ${payload.subject.subject_id}
- **筛查时间**: ${new Date(payload.created_at).toLocaleString()}
- **一致性级别**: ${payload.integrated_report?.consistency_level || '未知'}

### 筛查指标评估
${payload.protocol_results.map(r => `
#### 【${r.protocol === 'static_posture' ? '静态姿势' : r.protocol === 'adams_forward_bend' ? 'Adams前屈' : '深蹲'}】
- **评估状态**: ${r.status === 'completed' ? '正常完成' : '未完成'} (质量: ${r.capture_quality})
- **PSI 对称指数**: ${r.psi_score != null ? r.psi_score : '无'}
- **评估发现**: ${r.findings.join('；') || '未见异常'}
- **风险标识**: ${r.risk_flags.join('；') || '低风险'}
- **严重度等级**: ${r.severity_grades ? JSON.stringify(r.severity_grades) : '无'}
- **推荐行动**: ${r.recommendations.join('；') || '无'}
`).join('\n')}

### 大模型深度评估与临床背景
${payload.llm_analysis ? `
- **增强总结**: ${payload.llm_analysis.enhanced_summary || '无'}
- **临床背景**: ${payload.llm_analysis.clinical_context || '无'}
- **风险叙述**: ${payload.llm_analysis.risk_narrative || '无'}
- **建议措施**: ${payload.llm_analysis.suggestions.join('；') || '无'}
- **局限性**: ${payload.llm_analysis.limitations.join('；') || '无'}
` : '（大模型评估未生成或未同步）'}
        `,
        markdownReport: payload.llm_analysis?.enhanced_summary || payload.integrated_report?.summary || ''
      };

      const assessment: Assessment = {
        id: crypto.randomUUID(),
        sessionId,
        patientId: patient.id,
        type: 'combined',
        mode: 'stepped',
        createdAt: screeningTime,
        data: {
          posture: postureData
        },
        notes: `由早筛同步导入: ${payload.session_id}`,
        status: 'completed'
      };

      const session = {
        id: sessionId,
        patientId: patient.id,
        sequence,
        createdAt: screeningTime,
        updatedAt: screeningTime,
        assessments: [assessment],
        status: 'completed' as const,
        notes: `由早筛同步导入会话: ${payload.session_id}`
      };

      // Ingest transactional records
      await db.transaction('rw', [db.sessions, db.assessments], async () => {
        await db.sessions.add(session);
        await db.assessments.add(assessment);
      });

      // Reload patients in state
      const patients = await db.patients.orderBy('createdAt').reverse().toArray();
      set({
        patients,
        currentPatient: patient,
        isLoading: false
      });

      return patient;
    } catch (error) {
      set({ error: error instanceof Error ? error.message : '导入失败', isLoading: false });
      throw error;
    }
  },

  importScaleAssessment: async (patientId: string, scaleData: ScaleAssessmentData, sessionId?: string): Promise<void> => {
    set({ isLoading: true, error: null });
    try {
      const patient = await db.patients.get(patientId);
      if (!patient) throw new Error('患者不存在');

      let targetSessionId = sessionId;
      let sequence = 1;

      if (!targetSessionId) {
        // Find latest session or create a new one
        const sessions = await db.sessions.where('patientId').equals(patientId).toArray();
        if (sessions.length > 0) {
          // Sort by sequence or createdAt descending
          sessions.sort((a, b) => b.createdAt - a.createdAt);
          targetSessionId = sessions[0].id;
          sequence = sessions[0].sequence;
        } else {
          targetSessionId = generateSessionId(patient.shortCode || patient.id, 1);
          const newSession = {
            id: targetSessionId,
            patientId,
            sequence: 1,
            createdAt: Date.now(),
            updatedAt: Date.now(),
            assessments: [],
            status: 'completed' as const,
            notes: '自动创建于量表导入'
          };
          await db.sessions.add(newSession);
        }
      }

      // Create a scale assessment record
      const scaleAssessment: Assessment = {
        id: crypto.randomUUID(),
        sessionId: targetSessionId,
        patientId,
        type: 'scale',
        mode: 'stepped',
        createdAt: Date.now(),
        data: {
          scale: scaleData
        },
        notes: `量表评估导入: ${scaleData.scaleName} (得分: ${scaleData.totalScore}/${scaleData.maxScore})`,
        status: 'completed'
      };

      // Add to assessments table
      await db.assessments.add(scaleAssessment);

      // Append to the session's assessments list
      const session = await db.sessions.get(targetSessionId);
      if (session) {
        const currentAssessments = session.assessments || [];
        session.assessments = [...currentAssessments, scaleAssessment];
        session.updatedAt = Date.now();
        await db.sessions.put(session);
      }

      // Also update patient's updatedAt
      await db.patients.update(patientId, { updatedAt: Date.now() });

      // Reload patients list to keep state fresh
      const patients = await db.patients.orderBy('createdAt').reverse().toArray();
      set((state) => {
        const nextCurrent = state.currentPatient?.id === patientId ? { ...state.currentPatient, updatedAt: Date.now() } : state.currentPatient;
        return {
          patients,
          currentPatient: nextCurrent,
          isLoading: false
        };
      });
    } catch (error) {
      set({ error: error instanceof Error ? error.message : '量表导入失败', isLoading: false });
      throw error;
    }
  }
}));

import type { Landmark, PostureIssue, PostureMetrics } from './posture';
import type { TemporalAnalysis } from '@/lib/posture-processor';
import type { StructuredCase, PatientInfo } from '@/store/useCaseStore';
import type { ROMData } from '@/plugins/rom/types';

export type AssessmentMode = 'realtime' | 'stepped' | 'voice';

export type AssessmentView = 'front' | 'side' | 'back';

export interface PostureAssessmentData {
  mode: AssessmentMode;
  view: AssessmentView;
  metrics?: PostureMetrics;
  issues?: PostureIssue[];
  landmarks?: Landmark[];
  confidence: number;
  /** 深度报告 - LLM解析的报告 */
  markdownReport?: string;
  /** 基础报告 - 根据规则得出的结论 */
  auxiliaryDiagnosis?: string;
  timeSeries?: TemporalAnalysis['timeSeries'];
}

export interface RomAssessmentData {
  items: ROMData[];
  summary?: string;
  recommendations?: string[];
}

export interface MedVoiceAssessmentData {
  mode: AssessmentMode;
  transcript: string;
  structuredCase: StructuredCase;
  patientInfo: PatientInfo;
  viewMode: 'standard' | 'soap';
}

export interface ScaleAnswer {
  questionId: number;
  questionText: string;
  category: 'pain' | 'function' | 'self_image' | 'mental_health' | 'satisfaction';
  score: number;      // 1 - 5 分
  answerText: string; // 选项文字
}

export interface ScaleAssessmentData {
  scaleId: 'SRS-22' | 'ODI' | 'VAS' | 'MBI' | 'Berg' | 'MMT' | 'MAS' | 'HAM-A';
  scaleName: string;
  filledBy: 'therapist' | 'patient' | 'parent';
  totalScore: number;
  maxScore: number;
  percentageScore: number; // 功能障碍率或百分比
  dimensions: {
    functionActive: number; // 功能活动维度分
    pain: number;           // 疼痛维度分
    selfImage: number;      // 自我形象维度分
    mentalHealth: number;   // 精神健康维度分
    satisfaction?: number;  // 治疗满意度分
  };
  answers: ScaleAnswer[];
  aiInterpretation?: string; // AI 对量表得分的多维医学解读
  createdAt: number;
}

export interface AdamsAssessmentData {
  atrDegrees: number;                       // ATR 躯干旋转度数 (0-30)
  atrDirection: 'left' | 'right' | 'none'; // 隆起方向 (左侧/右侧/无)
  shoulderAsymmetry: 'symmetrical' | 'left-higher' | 'right-higher'; // 双肩对称性 (对称/左侧偏高/右侧偏高)
  scapulaAsymmetry: 'symmetrical' | 'left-prominent' | 'right-prominent'; // 肩胛骨隆起 (对称/左侧隆起/右侧隆起)
  waistCreaseAsymmetry: 'symmetrical' | 'left-deeper' | 'right-deeper'; // 腰折痕对称性 (对称/左侧折痕深/右侧折痕深)
  spineCurveEstimate: 'straight' | 'c-shape-left' | 'c-shape-right' | 's-shape'; // 脊柱弯曲大致形态
  cobbAngleEstimate?: number;              // 估计 Cobb 角 (选填, 0-90)
  snapshotImage?: string;                  // 融合铅垂网格的 Base64 图像
  remarks?: string;                        // 康复师临床备注
  createdAt: number;                       // 评估时间戳
}

export interface Assessment {
  id: string;
  sessionId: string;
  patientId: string;
  type: 'posture' | 'rom' | 'medvoice' | 'combined' | 'scale' | 'adams';
  mode: AssessmentMode;
  createdAt: number;
  data: {
    posture?: PostureAssessmentData;
    rom?: RomAssessmentData;
    medvoice?: MedVoiceAssessmentData;
    scale?: ScaleAssessmentData;
    adams?: AdamsAssessmentData;
  };
  notes?: string;
  status: 'pending' | 'completed' | 'reviewed';
  isBaseline?: boolean;
}

export interface TreatmentPlanVersion {
  id: string;
  version: number;
  content: string;
  assessmentId?: string;
  sessionId?: string;
  sessionReportId?: string;
  sourceType?: 'assessment' | 'session-report';
  patientId: string;
  createdAt: string;
  updatedAt: string;
  createdBy: string;
  tags?: string[];
  notes?: string;
  isCurrent: boolean;
  assessmentData?: AssessmentRecord;
}

export interface AssessmentRecord {
  id: string;
  timestamp: string;
  patientId: string;
  assessmentType: 'front' | 'side' | 'back';
  imageData: string;
  landmarks: Array<{x: number; y: number}> | number[];
  angles: Record<string, number>;
  metrics: Record<string, any>;
  treatmentPlanId?: string;
  feedback?: string;
  improvement?: number;
}

export interface TimelineRecord {
  id: string;
  timestamp: string;
  type: 'assessment' | 'treatment' | 'followup';
  data: AssessmentRecord | TreatmentPlanVersion;
}

export interface TreatmentTimeline {
  patientId: string;
  records: TimelineRecord[];
}

