import { AssessmentRecord } from '../types/assessment';
import { APP_CONFIG } from '../config/appConfig';

const STORAGE_KEY = APP_CONFIG.STORAGE_KEYS.ASSESSMENT_RECORDS;
const STORAGE_VERSION = '1.0';
const MAX_IMAGE_SIZE = APP_CONFIG.STORAGE_LIMITS.MAX_IMAGE_SIZE;
const STORAGE_WARNING_THRESHOLD = APP_CONFIG.STORAGE_LIMITS.WARNING_THRESHOLD;
const STORAGE_CRITICAL_THRESHOLD = APP_CONFIG.STORAGE_LIMITS.CRITICAL_THRESHOLD;
const MAX_RECORDS_COUNT = APP_CONFIG.STORAGE_LIMITS.MAX_RECORDS_COUNT;

interface StorageData {
  version: string;
  records: AssessmentRecord[];
  lastUpdated: string;
}

export class AssessmentRecordStorage {
  static saveRecord(record: AssessmentRecord): boolean {
    try {
      const records = this.loadRecords(record.patientId);
      const existingIndex = records.findIndex(r => r.id === record.id);
      
      if (existingIndex >= 0) {
        records[existingIndex] = record;
      } else {
        if (records.length >= MAX_RECORDS_COUNT) {
          console.warn(`评估记录数量已达上限 (${MAX_RECORDS_COUNT})，建议清理旧记录`);
          return false;
        }
        records.push(record);
      }
      
      const data: StorageData = {
        version: STORAGE_VERSION,
        records,
        lastUpdated: new Date().toISOString(),
      };
      
      const dataStr = JSON.stringify(data);
      const dataSize = new Blob([dataStr]).size;
      
      if (dataSize > STORAGE_CRITICAL_THRESHOLD) {
        console.error(`存储容量已达临界值 (${(dataSize / 1024 / 1024).toFixed(2)}MB)，无法保存`);
        return false;
      }
      
      if (dataSize > STORAGE_WARNING_THRESHOLD) {
        console.warn(`存储容量接近上限 (${(dataSize / 1024 / 1024).toFixed(2)}MB)，建议清理旧记录`);
      }
      
      localStorage.setItem(`${STORAGE_KEY}_${record.patientId}`, dataStr);
      return true;
    } catch (error) {
      console.error('保存评估记录失败:', error);
      return false;
    }
  }

  static loadRecords(patientId: string): AssessmentRecord[] {
    try {
      const dataStr = localStorage.getItem(`${STORAGE_KEY}_${patientId}`);
      if (!dataStr) return [];

      const data: StorageData = JSON.parse(dataStr);
      
      if (data.version !== STORAGE_VERSION) {
        console.warn('评估记录数据格式不匹配，将清空数据');
        this.clearRecords(patientId);
        return [];
      }

      return data.records || [];
    } catch (error) {
      console.error('加载评估记录失败:', error);
      return [];
    }
  }

  static getRecord(id: string, patientId: string): AssessmentRecord | null {
    const records = this.loadRecords(patientId);
    return records.find(r => r.id === id) || null;
  }

  static deleteRecord(id: string, patientId: string): boolean {
    try {
      const records = this.loadRecords(patientId);
      const filtered = records.filter(r => r.id !== id);
      
      const data: StorageData = {
        version: STORAGE_VERSION,
        records: filtered,
        lastUpdated: new Date().toISOString(),
      };
      localStorage.setItem(`${STORAGE_KEY}_${patientId}`, JSON.stringify(data));
      return true;
    } catch (error) {
      console.error('删除评估记录失败:', error);
      return false;
    }
  }

  static clearRecords(patientId: string): boolean {
    try {
      localStorage.removeItem(`${STORAGE_KEY}_${patientId}`);
      return true;
    } catch (error) {
      console.error('清空评估记录失败:', error);
      return false;
    }
  }

  static exportData(patientId: string): string {
    const records = this.loadRecords(patientId);
    const exportData = {
      version: STORAGE_VERSION,
      patientId,
      exportDate: new Date().toISOString(),
      records,
    };
    return JSON.stringify(exportData, null, 2);
  }

  static importData(jsonStr: string, patientId: string): boolean {
    try {
      const data = JSON.parse(jsonStr);
      
      if (!data.records || !Array.isArray(data.records)) {
        throw new Error('无效的数据格式');
      }

      const records: AssessmentRecord[] = data.records.map((r: any) => ({
        id: r.id,
        timestamp: r.timestamp,
        patientId,
        assessmentType: r.assessmentType,
        imageData: r.imageData,
        landmarks: r.landmarks || [],
        angles: r.angles || {},
        metrics: r.metrics || {},
        treatmentPlanId: r.treatmentPlanId,
        feedback: r.feedback,
        improvement: r.improvement,
      }));

      const storageData: StorageData = {
        version: STORAGE_VERSION,
        records,
        lastUpdated: new Date().toISOString(),
      };
      localStorage.setItem(`${STORAGE_KEY}_${patientId}`, JSON.stringify(storageData));
      return true;
    } catch (error) {
      console.error('导入评估记录失败:', error);
      return false;
    }
  }

  static getStorageInfo(patientId: string): { 
    used: number; 
    count: number; 
    available: boolean;
    warningLevel: 'normal' | 'warning' | 'critical';
    usedPercentage: number;
  } {
    try {
      const dataStr = localStorage.getItem(`${STORAGE_KEY}_${patientId}`);
      if (!dataStr) return { 
        used: 0, 
        count: 0, 
        available: true,
        warningLevel: 'normal',
        usedPercentage: 0
      };

      const data: StorageData = JSON.parse(dataStr);
      const used = dataStr ? new Blob([dataStr]).size : 0;
      
      let warningLevel: 'normal' | 'warning' | 'critical' = 'normal';
      if (used > STORAGE_CRITICAL_THRESHOLD) {
        warningLevel = 'critical';
      } else if (used > STORAGE_WARNING_THRESHOLD) {
        warningLevel = 'warning';
      }
      
      const usedPercentage = (used / STORAGE_CRITICAL_THRESHOLD) * 100;
      
      return { 
        used, 
        count: data.records.length, 
        available: warningLevel !== 'critical',
        warningLevel,
        usedPercentage: Math.min(100, usedPercentage)
      };
    } catch (error) {
      return { 
        used: 0, 
        count: 0, 
        available: false,
        warningLevel: 'normal',
        usedPercentage: 0
      };
    }
  }

  static validateImageSize(base64: string): boolean {
    const size = new Blob([base64]).size;
    return size <= MAX_IMAGE_SIZE;
  }

  static cleanupOldRecords(patientId: string, keepDays: number = 30): number {
    try {
      const records = this.loadRecords(patientId);
      const cutoffDate = new Date();
      cutoffDate.setDate(cutoffDate.getDate() - keepDays);
      
      const filtered = records.filter(r => new Date(r.timestamp) >= cutoffDate);
      
      const data: StorageData = {
        version: STORAGE_VERSION,
        records: filtered,
        lastUpdated: new Date().toISOString(),
      };
      localStorage.setItem(`${STORAGE_KEY}_${patientId}`, JSON.stringify(data));
      
      return records.length - filtered.length;
    } catch (error) {
      console.error('清理旧记录失败:', error);
      return 0;
    }
  }
}

import { AssessmentRecordStorage } from './assessmentRecordStorage';
import { TreatmentPlanStorage } from './treatmentPlanStorage';
import type { AssessmentRecord, TreatmentPlanVersion } from '../types/assessment';

export interface PatientDataExport {
  version: string;
  patientId: string;
  exportDate: string;
  assessments: AssessmentRecord[];
  treatmentPlans: TreatmentPlanVersion[];
  metadata: {
    assessmentCount: number;
    treatmentPlanCount: number;
    totalSize: number;
  };
}

export const exportPatientData = (patientId: string): string => {
  const assessments = AssessmentRecordStorage.loadRecords(patientId);
  const treatmentPlans = TreatmentPlanStorage.loadVersions();
  
  const exportData: PatientDataExport = {
    version: '1.0',
    patientId,
    exportDate: new Date().toISOString(),
    assessments,
    treatmentPlans,
    metadata: {
      assessmentCount: assessments.length,
      treatmentPlanCount: treatmentPlans.length,
      totalSize: 0,
    },
  };
  
  const jsonString = JSON.stringify(exportData, null, 2);
  exportData.metadata.totalSize = new Blob([jsonString]).size;
  
  return JSON.stringify(exportData, null, 2);
};

export const importPatientData = (jsonStr: string, patientId: string): boolean => {
  try {
    const data = JSON.parse(jsonStr);
    
    if (!data.assessments || !Array.isArray(data.assessments)) {
      throw new Error('无效的评估数据格式');
    }
    
    if (!data.treatmentPlans || !Array.isArray(data.treatmentPlans)) {
      throw new Error('无效的治疗计划数据格式');
    }
    
    const assessments: AssessmentRecord[] = data.assessments.map((r: any) => ({
      id: r.id,
      timestamp: r.timestamp,
      patientId,
      assessmentType: r.assessmentType,
      imageData: r.imageData,
      landmarks: r.landmarks || [],
      angles: r.angles || {},
      metrics: r.metrics || {},
      treatmentPlanId: r.treatmentPlanId,
      feedback: r.feedback,
      improvement: r.improvement,
    }));
    
    const treatmentPlans: TreatmentPlanVersion[] = data.treatmentPlans.map((p: any) => ({
      id: p.id,
      version: p.version,
      content: p.content,
      assessmentId: p.assessmentId,
      patientId,
      createdAt: p.createdAt,
      updatedAt: p.updatedAt,
      createdBy: p.createdBy,
      tags: p.tags,
      notes: p.notes,
      isCurrent: p.isCurrent,
    }));
    
    const success1 = AssessmentRecordStorage.importData(
      JSON.stringify({
        version: '1.0',
        patientId,
        exportDate: new Date().toISOString(),
        records: assessments,
      }),
      patientId
    );
    
    const success2 = TreatmentPlanStorage.importData(
      JSON.stringify({
        version: '1.0',
        versions: treatmentPlans,
        lastUpdated: new Date().toISOString(),
      })
    );
    
    return success1 && success2;
  } catch (error) {
    console.error('导入患者数据失败:', error);
    return false;
  }
};

export const downloadPatientData = (patientId: string, filename?: string): void => {
  const data = exportPatientData(patientId);
  const blob = new Blob([data], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename || `patient_data_${patientId}_${new Date().toISOString().split('T')[0]}.json`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
};

export const uploadPatientData = (file: File, patientId: string): Promise<boolean> => {
  return new Promise((resolve) => {
    const reader = new FileReader();
    reader.onload = (event) => {
      const content = event.target?.result as string;
      const success = importPatientData(content, patientId);
      resolve(success);
    };
    reader.onerror = () => {
      console.error('文件读取失败');
      resolve(false);
    };
    reader.readAsText(file);
  });
};

export const validatePatientData = (jsonStr: string): { valid: boolean; error?: string } => {
  try {
    const data = JSON.parse(jsonStr);
    
    if (!data.version) {
      return { valid: false, error: '缺少版本信息' };
    }
    
    if (!data.assessments || !Array.isArray(data.assessments)) {
      return { valid: false, error: '无效的评估数据' };
    }
    
    if (!data.treatmentPlans || !Array.isArray(data.treatmentPlans)) {
      return { valid: false, error: '无效的治疗计划数据' };
    }
    
    return { valid: true };
  } catch (error) {
    return { 
      valid: false, 
      error: error instanceof Error ? error.message : '数据解析失败' 
    };
  }
};

export const getPatientDataSummary = (patientId: string): {
  assessmentCount: number;
  treatmentPlanCount: number;
  totalSize: number;
  lastAssessmentDate: string | null;
  lastTreatmentPlanDate: string | null;
} => {
  const assessments = AssessmentRecordStorage.loadRecords(patientId);
  const treatmentPlans = TreatmentPlanStorage.loadVersions();
  
  const lastAssessment = assessments.length > 0 
    ? assessments[assessments.length - 1]
    : null;
  const lastTreatmentPlan = treatmentPlans.length > 0
    ? treatmentPlans[treatmentPlans.length - 1]
    : null;
  
  const assessmentStorage = AssessmentRecordStorage.getStorageInfo(patientId);
  const treatmentPlanStorage = TreatmentPlanStorage.getStorageInfo();
  
  return {
    assessmentCount: assessments.length,
    treatmentPlanCount: treatmentPlans.length,
    totalSize: assessmentStorage.used + treatmentPlanStorage.used,
    lastAssessmentDate: lastAssessment?.timestamp || null,
    lastTreatmentPlanDate: lastTreatmentPlan?.updatedAt || null,
  };
};

export function charToDigit(c: string): number {
  if (c >= '0' && c <= '9') {
    return parseInt(c, 10);
  }
  if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z')) {
    return c.toUpperCase().charCodeAt(0) - 'A'.charCodeAt(0) + 10;
  }
  return 0;
}

export function calculateLuhnMod10(payload: string): number {
  const cleanStr = payload.replace(/-/g, '').replace(/\s/g, '').toUpperCase();
  let total = 0;
  const reversedStr = cleanStr.split('').reverse().join('');
  for (let i = 0; i < reversedStr.length; i++) {
    let val = charToDigit(reversedStr[i]);
    if (i % 2 === 1) {
      val *= 2;
      if (val > 9) {
        val = Math.floor(val % 10) + Math.floor(val / 10);
      }
    }
    total += val;
  }
  return (10 - (total % 10)) % 10;
}

export function generateSUC(org: string, yymm: string, seq: number): string {
  const formattedSeq = String(seq).padStart(4, '0');
  const base = `QY-${org.toUpperCase()}-${yymm}-${formattedSeq}`;
  const checksum = calculateLuhnMod10(base);
  return `${base}-${checksum}`;
}

export function verifySUC(suc: string): boolean {
  if (!suc) return false;
  const parts = suc.split('-');
  if (parts.length !== 5) return false;
  if (parts[0] !== 'QY') return false;

  const base = parts.slice(0, 4).join('-');
  try {
    const expectedChecksum = calculateLuhnMod10(base);
    const actualChecksum = parseInt(parts[4], 10);
    return expectedChecksum === actualChecksum;
  } catch (e) {
    return false;
  }
}

import { TreatmentPlanVersion } from '../types/assessment';
import { APP_CONFIG } from '../config/appConfig';

const STORAGE_KEY = APP_CONFIG.STORAGE_KEYS.TREATMENT_PLANS;
const STORAGE_VERSION = '1.0';

interface StorageData {
  version: string;
  versions: TreatmentPlanVersion[];
  lastUpdated: string;
}

export class TreatmentPlanStorage {
  static saveVersions(versions: TreatmentPlanVersion[]): boolean {
    try {
      const data: StorageData = {
        version: STORAGE_VERSION,
        versions,
        lastUpdated: new Date().toISOString(),
      };
      localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
      return true;
    } catch (error) {
      console.error('保存版本数据失败:', error);
      return false;
    }
  }

  static loadVersions(): TreatmentPlanVersion[] {
    try {
      const dataStr = localStorage.getItem(STORAGE_KEY);
      if (!dataStr) return [];

      const data: StorageData = JSON.parse(dataStr);
      
      if (data.version !== STORAGE_VERSION) {
        console.warn('版本数据格式不匹配，将清空数据');
        this.clearVersions();
        return [];
      }

      return data.versions || [];
    } catch (error) {
      console.error('加载版本数据失败:', error);
      return [];
    }
  }

  static clearVersions(): boolean {
    try {
      localStorage.removeItem(STORAGE_KEY);
      return true;
    } catch (error) {
      console.error('清空版本数据失败:', error);
      return false;
    }
  }

  static exportData(): string {
    const versions = this.loadVersions();
    const exportData = {
      version: STORAGE_VERSION,
      exportDate: new Date().toISOString(),
      versions,
    };
    return JSON.stringify(exportData, null, 2);
  }

  static importData(jsonStr: string): boolean {
    try {
      const data = JSON.parse(jsonStr);
      
      if (!data.versions || !Array.isArray(data.versions)) {
        throw new Error('无效的数据格式');
      }

      const versions: TreatmentPlanVersion[] = data.versions.map((v: any) => ({
        id: v.id,
        version: v.version,
        content: v.content,
        assessmentId: v.assessmentId,
        sessionId: v.sessionId,
        sessionReportId: v.sessionReportId,
        sourceType: v.sourceType || (v.sessionReportId ? 'session-report' : 'assessment'),
        patientId: v.patientId,
        createdAt: v.createdAt,
        updatedAt: v.updatedAt,
        createdBy: v.createdBy || 'imported',
        tags: v.tags || [],
        notes: v.notes || '',
        isCurrent: v.isCurrent || false,
      }));

      return this.saveVersions(versions);
    } catch (error) {
      console.error('导入版本数据失败:', error);
      return false;
    }
  }

  static getStorageInfo(): { used: number; available: boolean } {
    try {
      const data = localStorage.getItem(STORAGE_KEY);
      const used = data ? new Blob([data]).size : 0;
      return { used, available: true };
    } catch (error) {
      return { used: 0, available: false };
    }
  }
}
